(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-083"]={"sura":83,"name_ar":"المطففين","name_en":"Al-Mutaffifin","verses":36,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":36,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=6\" class=\"link\">83:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:6 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=6\" class=\"link\">83:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:6 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=6\" class=\"link\">83:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:6 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=6\" class=\"link\">83:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:6 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=6\" class=\"link\">83:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:6 ஐ பார்க்கவும்"},"6":{"html":"<strong>இது மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>அளவையிலும் நிறுவையிலும் அதிகரிப்பதும் குறைப்பதும் வருத்தத்திற்கும் நஷ்டத்திற்கும் காரணமாகும்</strong><br />\r\n<br />\r\nஅந்-நஸாயீ மற்றும் இப்னு மாஜா ஆகிய இருவரும் இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்ததாகப் பின்வருமாறு பதிவு செய்துள்ளனர்: \"நபியவர்கள் (ஸல்) மதீனாவிற்கு வந்தபோது, மதீனா வாசிகள் அளப்பதில் மிக மோசமானவர்களாக (அளவை மோசடி செய்பவர்களாக) இருந்தனர். எனவே, அல்லாஹ் பின்வரும் வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَيۡلٌ۬</span> <span class=\"quran-arabic-font text-success\">لِّلۡمُطَفِّفِينَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n<br />\r\n(அளவைகளில் மோசடி செய்பவர்களுக்குக் கேடுதான்.) இதன் பிறகு, அவர்கள் அளவைகளைச் சரியாகக் கொடுக்கத் தொடங்கினர்.\" இங்கு 'தத்ஃபீஃப்' (Tatfif) என்ற சொல்லின் பொருள், அளவையிலும் நிறுவையிலும் கஞ்சத்தனம் செய்வதாகும். அதாவது, மற்றவர்களிடமிருந்து தனக்கு வர வேண்டியிருந்தால் அதை அதிகப்படுத்துவதும், தான் மற்றவர்களுக்குக் கொடுக்க வேண்டியிருந்தால் அதைக் குறைப்பதும் ஆகும். எனவே, யாருக்கு நஷ்டமும் அழிவும் உண்டென அல்லாஹ் எச்சரித்தானோ அந்த 'முதஃப்பிஃபீன்கள்' (Mutaffifin) என்பவர்கள் யார் என்பதை அவன் விளக்குகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">ٱلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">ٱكۡتَالُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ٱلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n<br />\r\n(அவர்கள் மக்களிடமிருந்து அளந்து வாங்கும் போது,) அதாவது மக்களிடமிருந்து பெறும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">يَسۡتَوۡفُونَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n<br />\r\n(நிறைவாகப் பெற்றுக்கொள்கிறார்கள்.) அதாவது, அவர்கள் தங்கள் உரிமையை முழுமையாகவும் கூடுதலாகவும் கேட்டுப் பெற்றுக்கொள்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">كَالُوهُمۡ</span> <span class=\"quran-arabic-font text-success\">أَو</span> <span class=\"quran-arabic-font text-success\">وَّزَنُوهُمۡ</span> <span class=\"quran-arabic-font text-success\">يُخۡسِرُونَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n<br />\r\n(அவர்கள் மற்றவர்களுக்கு அளந்தோ அல்லது நிறுத்தோ கொடுக்கும் போது, குறைவாகக் கொடுக்கிறார்கள்.) அதாவது, அவர்கள் குறைக்கிறார்கள். நிச்சயமாக, அளவையும் நிறுவையையும் முழுமையாகக் கொடுக்கும்படி அல்லாஹ் கட்டளையிட்டுள்ளான். அவன் வேறொரு வசனத்தில் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَأَوۡفُواْ</span> <span class=\"quran-arabic-font text-success\">ٱلۡكَيۡلَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">كِلۡتُمۡ</span> <span class=\"quran-arabic-font text-success\">وَزِنُواْ</span> <span class=\"quran-arabic-font text-success\">بِٱلۡقِسۡطَاسِ</span> <span class=\"quran-arabic-font text-success\">ٱلۡمُسۡتَقِيمِ</span>‌<span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">ذَٲلِكَ</span> <span class=\"quran-arabic-font text-success\">خَيۡرٌ۬</span> <span class=\"quran-arabic-font text-success\">وَأَحۡسَنُ</span> <span class=\"quran-arabic-font text-success\">تَأۡوِيلاً۬</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n<br />\r\n(நீங்கள் அளக்கும்போது முழுமையாக அளங்கள்; மேலும் சரியான தராசைக் கொண்டு நிறுங்கள். அதுவே மிகச் சிறந்ததும், முடிவில் அழகானதுமாகும்.) (<a href=\"qurandisp.php?sura=17&ayah=35\" class=\"link\">17:35</a>). அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَأَوۡفُواْ</span> <span class=\"quran-arabic-font text-success\">ٱلۡڪَيۡلَ</span> <span class=\"quran-arabic-font text-success\">وَٱلۡمِيزَانَ</span> <span class=\"quran-arabic-font text-success\">بِٱلۡقِسۡطِ</span>‌<span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">نُكَلِّفُ</span> <span class=\"quran-arabic-font text-success\">نَفۡسًا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">وُسۡعَهَا</span>‌<span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n<br />\r\n(அளவையும் நிறுவையையும் நீதியுடன் முழுமையாக்குங்கள். நாம் எந்த ஓர் ஆத்மாவையும் அதன் சக்திக்கு மீறிச் சிரமப்படுத்துவதில்லை.) (<a href=\"qurandisp.php?sura=6&ayah=152\" class=\"link\">6:152</a>). மேலும் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَأَقِيمُواْ</span> <span class=\"quran-arabic-font text-success\">ٱلۡوَزۡنَ</span> <span class=\"quran-arabic-font text-success\">بِٱلۡقِسۡطِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تُخۡسِرُواْ</span> <span class=\"quran-arabic-font text-success\">ٱلۡمِيزَانَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n<br />\r\n(மேலும், நீங்கள் நீதியுடன் நிறுவையை நிலைநாட்டுங்கள்; எடையைக் குறைக்காதீர்கள்.) (<a href=\"qurandisp.php?sura=55&ayah=9\" class=\"link\">55:9</a>). அளவையிலும் நிறுவையிலும் மோசடி செய்த காரணத்தினாலேயே அல்லாஹ் ஷுஐப் (அலை) அவர்களின் சமூகத்தினரை அழித்து ஒழித்தான்.<br />\r\n<br />\r\n<strong>அகிலத்தாரின் அதிபதிக்கு முன்னால் நிற்பதைக் குறித்து முதஃப்பிஃபீன்களுக்கு விடுக்கப்படும் எச்சரிக்கை</strong><br />\r\n<br />\r\nபின்னர் அவர்களை அச்சுறுத்தும் விதமாக அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلا</span> <span class=\"quran-arabic-font text-success\">يَظُنُّ</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّبْعُوثُونَ</span> - <span class=\"quran-arabic-font text-success\">لِيَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span><br />\r\n<br />\r\n(அவர்கள் ஒரு மகத்தான நாளில் மீண்டும் எழுப்பப்படுவார்கள் என்பதை எண்ணிப் பார்க்கவில்லையா?) அதாவது, மறைவான விஷயங்களையும் உள்ளத்தின் ரகசியங்களையும் அறிந்தவனுக்கு முன்னால், பெரும் திகிலும் அச்சமும் நிறைந்த ஒரு நாளில் மீண்டும் எழுப்பப்பட்டு நிற்பதை இம்மக்கள் அஞ்சவில்லையா? அந்நாளில் எவர் நஷ்டமடைகிறாரோ அவர் கொழுந்துவிட்டெரியும் நரக நெருப்பில் தள்ளப்படுவார். பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُومُ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">لِرَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ</span><br />\r\n<br />\r\n(அந்நாளில் மனிதர்கள் அகிலத்தாரின் அதிபதிக்கு முன்னால் நிற்பார்கள்.) அதாவது, குற்றவாளிகளுக்கு மிகவும் கடினமானதும் துயரம் நிறைந்ததுமான அந்த இடத்தில், அவர்கள் செருப்பின்றியும் நிர்வாணமாகவும் விருத்தசேதனம் செய்யப்படாதவர்களாகவும் நிற்பார்கள். அவர்கள் அல்லாஹ்வின் கட்டளையால் சூழப்பட்டிருப்பார்கள்; அது அவர்களின் பலத்திற்கும் உணர்வுகளுக்கும் அப்பாற்பட்டதாக இருக்கும். இமாம் மாலிக் அவர்கள் நாஃபிஉ வழியாக, இப்னு உமர் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: நபியவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُومُ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">لِرَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ،</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَغِيبَ</span> <span class=\"quran-arabic-font text-success\">أَحَدُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">رَشْحِهِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَنْصَافِ</span> <span class=\"quran-arabic-font text-success\">أُذُنَيْه</span>»<br />\r\n<br />\r\n(மனிதர்கள் அகிலத்தாரின் அதிபதிக்கு முன்னால் நிற்கும் அந்த நாளில், அவர்களில் ஒருவர் தனது காதுகளின் பாதி வரை வியர்வையில் மூழ்கும் வரை அந்நிலை நீடிக்கும்.) இந்த ஹதீஸை அல்-புகாரீ அவர்கள் மாலிக் மற்றும் அப்துல்லாஹ் பின் அவ்ன் ஆகியோரிடமிருந்து பதிவு செய்துள்ளார்; இவ்விருவரும் நாஃபிஉவிடமிருந்து இதனை அறிவித்துள்ளனர். முஸ்லிம் அவர்களும் இதனை இரண்டு வழிகளில் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\nமற்றொரு ஹதீஸ்: இமாம் அஹ்மத் அவர்கள், இப்னுல் அஸ்வத் அல்-கிந்தீ என்றழைக்கப்படும் அல்-மிக்தாத் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">يَوْمُ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">أُدْنِيَتِ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْعِبَادِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَكُونَ</span> <span class=\"quran-arabic-font text-success\">قَدْرَ</span> <span class=\"quran-arabic-font text-success\">مِيلٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مِيلَيْنِ</span> <span class=\"quran-arabic-font text-success\">قال</span> <span class=\"quran-arabic-font text-success\">فَتَصْهَرُهُمُ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسُ</span> <span class=\"quran-arabic-font text-success\">فَيَكُونُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْعَرَقِ</span> <span class=\"quran-arabic-font text-success\">كَقَدْرِ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالِهِمْ،</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَأْخُذُهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">عَقِبَيْهِ،</span> <span class=\"quran-arabic-font text-success\">وَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَأْخُذُهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رُكْبَتَيْهِ،</span> <span class=\"quran-arabic-font text-success\">وَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَأْخُذُهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">حَقْوَيْهِ،</span> <span class=\"quran-arabic-font text-success\">وَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يُلْجِمُهُ</span> <span class=\"quran-arabic-font text-success\">إِلْجَامًا</span>»<br />\r\n<br />\r\n(மறுமை நாளில், சூரியன் அடியார்களுக்கு மிக நெருக்கமாகக் கொண்டு வரப்படும்; அது அவர்களிடமிருந்து ஒரு மைல் அல்லது இரண்டு மைல் தொலைவிலேயே இருக்கும். சூரியன் அவர்களை உருக்கும், மேலும் அவர்கள் தங்கள் செயல்களின் அளவிற்கு ஏற்ப வியர்வையில் மூழ்கியிருப்பார்கள். அவர்களில் சிலருக்கு வியர்வை அவர்களது இரண்டு கணுக்கால்கள் வரை இருக்கும்; சிலருக்கு முழங்கால்கள் வரை இருக்கும்; சிலருக்கு இடுப்பு வரை இருக்கும்; இன்னும் சிலருக்கு வியர்வை (கழுத்து வரை உயர்ந்து) கடிவாளமிட்டது போல் இருக்கும்.) இந்த ஹதீஸை முஸ்லிம் மற்றும் அத்-திர்மிதீ ஆகியோர் பதிவு செய்துள்ளனர். சுனன் அபூ தாவூதில், 'மறுமை நாளில் நிற்பதன் சிரமங்களிலிருந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பாதுகாப்புத் தேடுவார்கள்' என்று பதிவு செய்யப்பட்டுள்ளது. இப்னு மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: மக்கள் வானத்தை நோக்கித் தலைகளை உயர்த்தியவாறு நாற்பது ஆண்டுகள் நிற்பார்கள். எவரும் அவர்களுடன் பேசமாட்டார்கள்; நல்லவர் கெட்டவர் என அனைவரும் வியர்வையால் கடிவாளமிடப்பட்டிருப்பார்கள். இப்னு உமர் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அவர்கள் நூறு ஆண்டுகள் (அங்கு) நிற்பார்கள். இவ்விரு கூற்றுகளையும் இப்னு ஜரீர் பதிவு செய்துள்ளார். சுனன் அபூ தாவூத், அந்-நஸாயீ மற்றும் இப்னு மாஜா ஆகிய நூல்களில் ஆயிஷா (ரழி) அவர்கள் அறிவித்ததாகப் பின்வருமாறு பதிவாகியுள்ளது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமது இரவுத் தொழுகையைத் தொடங்கும் போது பத்து முறை அல்லாஹ்வின் பெருமையையும், பத்து முறை அல்லாஹ்வின் புகழையும், பத்து முறை அல்லாஹ்வைத் துதிப்பதையும் மற்றும் பத்து முறை அல்லாஹ்விடம் மன்னிப்புக் கோருவதையும் வழக்கமாகக் கொண்டிருந்தார்கள். பிறகு அவர்கள் கூறுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">وَاهْدِنِي</span> <span class=\"quran-arabic-font text-success\">وَارْزُقْنِي</span> <span class=\"quran-arabic-font text-success\">وَعَافِنِي</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! என்னை மன்னிப்பாயாக, எனக்கு நேர்வழி காட்டுவாயாக, எனக்கு வாழ்வாதாரம் வழங்குவாயாக, எனக்கு நல்வாழ்வு அளிப்பாயாக.) பின்னர் அவர்கள் மறுமை நாளில் நிற்பதன் சிரமங்களிலிருந்து பாதுகாப்புத் தேடுவார்கள்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"இது மதீனாவில் அருளப்பட்டது\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஅளவையிலும் நிறுவையிலும் அதிகரிப்பதும் குறைப்பதும் வருத்தத்திற்கும் நஷ்டத்திற்கும் காரணமாகும்\n\r\n\n\r\nஅந்-நஸாயீ மற்றும் இப்னு மாஜா ஆகிய இருவரும் இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்ததாகப் பின்வருமாறு பதிவு செய்துள்ளனர்: \"நபியவர்கள் (ஸல்) மதீனாவிற்கு வந்தபோது, மதீனா வாசிகள் அளப்பதில் மிக மோசமானவர்களாக (அளவை மோசடி செய்பவர்களாக) இருந்தனர். எனவே, அல்லாஹ் பின்வரும் வசனத்தை அருளினான்:\n\r\n\n\r\n﴿ وَيۡلٌ۬ لِّلۡمُطَفِّفِينَ ﴾\n\r\n\n\r\n(அளவைகளில் மோசடி செய்பவர்களுக்குக் கேடுதான்.) இதன் பிறகு, அவர்கள் அளவைகளைச் சரியாகக் கொடுக்கத் தொடங்கினர்.\" இங்கு 'தத்ஃபீஃப்' (Tatfif) என்ற சொல்லின் பொருள், அளவையிலும் நிறுவையிலும் கஞ்சத்தனம் செய்வதாகும். அதாவது, மற்றவர்களிடமிருந்து தனக்கு வர வேண்டியிருந்தால் அதை அதிகப்படுத்துவதும், தான் மற்றவர்களுக்குக் கொடுக்க வேண்டியிருந்தால் அதைக் குறைப்பதும் ஆகும். எனவே, யாருக்கு நஷ்டமும் அழிவும் உண்டென அல்லாஹ் எச்சரித்தானோ அந்த 'முதஃப்பிஃபீன்கள்' (Mutaffifin) என்பவர்கள் யார் என்பதை அவன் விளக்குகிறான்:\n\r\n\n\r\n﴿ ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ ﴾\n\r\n\n\r\n(அவர்கள் மக்களிடமிருந்து அளந்து வாங்கும் போது,) அதாவது மக்களிடமிருந்து பெறும்போது,\n\r\n\n\r\n﴿ يَسۡتَوۡفُونَ ﴾\n\r\n\n\r\n(நிறைவாகப் பெற்றுக்கொள்கிறார்கள்.) அதாவது, அவர்கள் தங்கள் உரிமையை முழுமையாகவும் கூடுதலாகவும் கேட்டுப் பெற்றுக்கொள்கிறார்கள்.\n\r\n\n\r\n﴿ وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ ﴾\n\r\n\n\r\n(அவர்கள் மற்றவர்களுக்கு அளந்தோ அல்லது நிறுத்தோ கொடுக்கும் போது, குறைவாகக் கொடுக்கிறார்கள்.) அதாவது, அவர்கள் குறைக்கிறார்கள். நிச்சயமாக, அளவையும் நிறுவையையும் முழுமையாகக் கொடுக்கும்படி அல்லாஹ் கட்டளையிட்டுள்ளான். அவன் வேறொரு வசனத்தில் கூறுகிறான்:\n\r\n\n\r\n﴿ وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ‌ۚ ذَٲلِكَ خَيۡرٌ۬ وَأَحۡسَنُ تَأۡوِيلاً۬ ﴾\n\r\n\n\r\n(நீங்கள் அளக்கும்போது முழுமையாக அளங்கள்; மேலும் சரியான தராசைக் கொண்டு நிறுங்கள். அதுவே மிகச் சிறந்ததும், முடிவில் அழகானதுமாகும்.) (17:35). அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\n﴿ وَأَوۡفُواْ ٱلۡڪَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِ‌ۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَا‌ۖ ﴾\n\r\n\n\r\n(அளவையும் நிறுவையையும் நீதியுடன் முழுமையாக்குங்கள். நாம் எந்த ஓர் ஆத்மாவையும் அதன் சக்திக்கு மீறிச் சிரமப்படுத்துவதில்லை.) (6:152). மேலும் அவன் கூறுகிறான்:\n\r\n\n\r\n﴿ وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ ﴾\n\r\n\n\r\n(மேலும், நீங்கள் நீதியுடன் நிறுவையை நிலைநாட்டுங்கள்; எடையைக் குறைக்காதீர்கள்.) (55:9). அளவையிலும் நிறுவையிலும் மோசடி செய்த காரணத்தினாலேயே அல்லாஹ் ஷுஐப் (அலை) அவர்களின் சமூகத்தினரை அழித்து ஒழித்தான்.\n\r\n\n\r\nஅகிலத்தாரின் அதிபதிக்கு முன்னால் நிற்பதைக் குறித்து முதஃப்பிஃபீன்களுக்கு விடுக்கப்படும் எச்சரிக்கை\n\r\n\n\r\nபின்னர் அவர்களை அச்சுறுத்தும் விதமாக அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَلا يَظُنُّ أُوْلَـئِكَ أَنَّهُمْ مَّبْعُوثُونَ - لِيَوْمٍ عَظِيمٍ\n\r\n\n\r\n(அவர்கள் ஒரு மகத்தான நாளில் மீண்டும் எழுப்பப்படுவார்கள் என்பதை எண்ணிப் பார்க்கவில்லையா?) அதாவது, மறைவான விஷயங்களையும் உள்ளத்தின் ரகசியங்களையும் அறிந்தவனுக்கு முன்னால், பெரும் திகிலும் அச்சமும் நிறைந்த ஒரு நாளில் மீண்டும் எழுப்பப்பட்டு நிற்பதை இம்மக்கள் அஞ்சவில்லையா? அந்நாளில் எவர் நஷ்டமடைகிறாரோ அவர் கொழுந்துவிட்டெரியும் நரக நெருப்பில் தள்ளப்படுவார். பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَـلَمِينَ\n\r\n\n\r\n(அந்நாளில் மனிதர்கள் அகிலத்தாரின் அதிபதிக்கு முன்னால் நிற்பார்கள்.) அதாவது, குற்றவாளிகளுக்கு மிகவும் கடினமானதும் துயரம் நிறைந்ததுமான அந்த இடத்தில், அவர்கள் செருப்பின்றியும் நிர்வாணமாகவும் விருத்தசேதனம் செய்யப்படாதவர்களாகவும் நிற்பார்கள். அவர்கள் அல்லாஹ்வின் கட்டளையால் சூழப்பட்டிருப்பார்கள்; அது அவர்களின் பலத்திற்கும் உணர்வுகளுக்கும் அப்பாற்பட்டதாக இருக்கும். இமாம் மாலிக் அவர்கள் நாஃபிஉ வழியாக, இப்னு உமர் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: நபியவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ، حَتَّى يَغِيبَ أَحَدُهُمْ فِي رَشْحِهِ إِلَى أَنْصَافِ أُذُنَيْه»\n\r\n\n\r\n(மனிதர்கள் அகிலத்தாரின் அதிபதிக்கு முன்னால் நிற்கும் அந்த நாளில், அவர்களில் ஒருவர் தனது காதுகளின் பாதி வரை வியர்வையில் மூழ்கும் வரை அந்நிலை நீடிக்கும்.) இந்த ஹதீஸை அல்-புகாரீ அவர்கள் மாலிக் மற்றும் அப்துல்லாஹ் பின் அவ்ன் ஆகியோரிடமிருந்து பதிவு செய்துள்ளார்; இவ்விருவரும் நாஃபிஉவிடமிருந்து இதனை அறிவித்துள்ளனர். முஸ்லிம் அவர்களும் இதனை இரண்டு வழிகளில் பதிவு செய்துள்ளார்.\n\r\n\n\r\nமற்றொரு ஹதீஸ்: இமாம் அஹ்மத் அவர்கள், இப்னுல் அஸ்வத் அல்-கிந்தீ என்றழைக்கப்படும் அல்-மிக்தாத் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا كَانَ يَوْمُ الْقِيَامَةِ أُدْنِيَتِ الشَّمْسُ مِنَ الْعِبَادِ حَتَّى تَكُونَ قَدْرَ مِيلٍ أَوْ مِيلَيْنِ قال فَتَصْهَرُهُمُ الشَّمْسُ فَيَكُونُونَ فِي الْعَرَقِ كَقَدْرِ أَعْمَالِهِمْ، مِنْهُمْ مَنْ يَأْخُذُهُ إِلَى عَقِبَيْهِ، وَمِنْهُمْ مَنْ يَأْخُذُهُ إِلَى رُكْبَتَيْهِ، وَمِنْهُمْ مَنْ يَأْخُذُهُ إِلَى حَقْوَيْهِ، وَمِنْهُمْ مَنْ يُلْجِمُهُ إِلْجَامًا»\n\r\n\n\r\n(மறுமை நாளில், சூரியன் அடியார்களுக்கு மிக நெருக்கமாகக் கொண்டு வரப்படும்; அது அவர்களிடமிருந்து ஒரு மைல் அல்லது இரண்டு மைல் தொலைவிலேயே இருக்கும். சூரியன் அவர்களை உருக்கும், மேலும் அவர்கள் தங்கள் செயல்களின் அளவிற்கு ஏற்ப வியர்வையில் மூழ்கியிருப்பார்கள். அவர்களில் சிலருக்கு வியர்வை அவர்களது இரண்டு கணுக்கால்கள் வரை இருக்கும்; சிலருக்கு முழங்கால்கள் வரை இருக்கும்; சிலருக்கு இடுப்பு வரை இருக்கும்; இன்னும் சிலருக்கு வியர்வை (கழுத்து வரை உயர்ந்து) கடிவாளமிட்டது போல் இருக்கும்.) இந்த ஹதீஸை முஸ்லிம் மற்றும் அத்-திர்மிதீ ஆகியோர் பதிவு செய்துள்ளனர். சுனன் அபூ தாவூதில், 'மறுமை நாளில் நிற்பதன் சிரமங்களிலிருந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பாதுகாப்புத் தேடுவார்கள்' என்று பதிவு செய்யப்பட்டுள்ளது. இப்னு மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: மக்கள் வானத்தை நோக்கித் தலைகளை உயர்த்தியவாறு நாற்பது ஆண்டுகள் நிற்பார்கள். எவரும் அவர்களுடன் பேசமாட்டார்கள்; நல்லவர் கெட்டவர் என அனைவரும் வியர்வையால் கடிவாளமிடப்பட்டிருப்பார்கள். இப்னு உமர் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அவர்கள் நூறு ஆண்டுகள் (அங்கு) நிற்பார்கள். இவ்விரு கூற்றுகளையும் இப்னு ஜரீர் பதிவு செய்துள்ளார். சுனன் அபூ தாவூத், அந்-நஸாயீ மற்றும் இப்னு மாஜா ஆகிய நூல்களில் ஆயிஷா (ரழி) அவர்கள் அறிவித்ததாகப் பின்வருமாறு பதிவாகியுள்ளது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமது இரவுத் தொழுகையைத் தொடங்கும் போது பத்து முறை அல்லாஹ்வின் பெருமையையும், பத்து முறை அல்லாஹ்வின் புகழையும், பத்து முறை அல்லாஹ்வைத் துதிப்பதையும் மற்றும் பத்து முறை அல்லாஹ்விடம் மன்னிப்புக் கோருவதையும் வழக்கமாகக் கொண்டிருந்தார்கள். பிறகு அவர்கள் கூறுவார்கள்:\n\r\n\n\r\n«اللْهُمَّ اغْفِرْ لِي وَاهْدِنِي وَارْزُقْنِي وَعَافِنِي»\n\r\n\n\r\n(யா அல்லாஹ்! என்னை மன்னிப்பாயாக, எனக்கு நேர்வழி காட்டுவாயாக, எனக்கு வாழ்வாதாரம் வழங்குவாயாக, எனக்கு நல்வாழ்வு அளிப்பாயாக.) பின்னர் அவர்கள் மறுமை நாளில் நிற்பதன் சிரமங்களிலிருந்து பாதுகாப்புத் தேடுவார்கள்."},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=17\" class=\"link\">83:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:17 ஐ பார்க்கவும்"},"17":{"html":"<strong>தீயோரின் பதிவேடும், அவர்களுக்கு நேரிடுபவை பற்றியும்</strong><br />\r\n<br />\r\nஅல்லாஹ் உண்மையாகவே கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">كِتَـٰبَ</span> <span class=\"quran-arabic-font text-success\">ٱلۡفُجَّارِ</span> <span class=\"quran-arabic-font text-success\">لَفِى</span> <span class=\"quran-arabic-font text-success\">سِجِّينٍ۬</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(இல்லை! நிச்சயமாகத் தீயோரின் பதிவேடு ஸிஜ்ஜீனில் இருக்கிறது.) அதாவது, அவர்களின் இறுதி இலக்கும் தங்குமிடமும் ஸிஜ்ஜீனில் இருக்கும். இது சிறை (ஸிஜ்ன்) என்ற சொல்லில் இருந்து உருவானதாகும், இங்கு இது நெருக்கடியான சூழலைக் குறிக்கிறது. இந்த விஷயத்தின் பாரதூரத்தை உணர்த்த அல்லாஹ் கூறுகிறான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَدۡرَٮٰكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سِجِّينٌ۬</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(ஸிஜ்ஜீன் என்றால் என்னவென்று உமக்கு எது அறிவிக்கும்?) அதாவது, அது ஒரு பாரிய விஷயம், நிரந்தரச் சிறை மற்றும் வலிமிகுந்த வேதனையாகும். இது ஏழாவது பூமிக்குக் கீழே இருப்பதாகச் சிலர் கூறியுள்ளனர். அல்-பரா இப்னு ஆஸிப் (ரழி) அவர்களின் நீண்ட ஹதீஸில், நபி (ஸல்) அவர்கள் பின்வருமாறு கூறியதாக முன்னரே குறிப்பிடப்பட்டுள்ளது:<br />\r\n<br />\r\n« <span class=\"quran-arabic-font text-success\">يَقُول</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">رُوحِ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِ</span> <span class=\"quran-arabic-font text-success\">اكْتُبُوا</span> <span class=\"quran-arabic-font text-success\">كِتَابَهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سِجِّينٍ</span>. <span class=\"quran-arabic-font text-success\">وَسِجِّينٌ</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">تَحْتُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">السَّابِعَة</span> »<br />\r\n(அல்லாஹ் ஒரு காஃபிரின் (நிராகரிப்பாளனின்) ஆன்மாவைப் பற்றிக் கூறும்போது, 'அவனது பதிவேட்டை ஸிஜ்ஜீனில் பதிவு செய்யுங்கள்' என்று கூறுவான். ஸிஜ்ஜீன் என்பது ஏழாவது பூமிக்குக் கீழே உள்ளதாகும்.) தீயவர்களின் தங்குமிடம் நரகமாகும் என்பது அனைவரும் அறிந்ததே. அது தாழ்ந்தவற்றில் மிகவும் தாழ்ந்த இடமாகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">رَدَدۡنَـٰهُ</span> <span class=\"quran-arabic-font text-success\">أَسۡفَلَ</span> <span class=\"quran-arabic-font text-success\">سَـٰفِلِينَ</span> • <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">ٱلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">ٱلصَّـٰلِحَـٰتِ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(பின்னர் நாம் அவனைத் தாழ்ந்தவர்களில் மிகத் தாழ்ந்தவனாக ஆக்கினோம். ஈமான் (நம்பிக்கை) கொண்டு நற்செயல்கள் செய்தவர்களைத் தவிர.) (<a href=\"qurandisp.php?sura=95&ayah=5\" class=\"link\">95:5</a>-6) அல்லாஹ் இங்கு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">كَلَّآ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">كِتَـٰبَ</span> <span class=\"quran-arabic-font text-success\">ٱلۡفُجَّارِ</span> <span class=\"quran-arabic-font text-success\">لَفِى</span> <span class=\"quran-arabic-font text-success\">سِجِّينٍ۬</span> • <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَدۡرَٮٰكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سِجِّينٌ۬</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(இல்லை! நிச்சயமாகத் தீயோரின் பதிவேடு ஸிஜ்ஜீனில் இருக்கிறது. ஸிஜ்ஜீன் என்றால் என்னவென்று உமக்கு எது அறிவிக்கும்?) அது துன்பமும் துயரமும் நிறைந்ததாகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَإِذَآ</span> <span class=\"quran-arabic-font text-success\">أُلۡقُواْ</span> <span class=\"quran-arabic-font text-success\">مِنۡہَا</span> <span class=\"quran-arabic-font text-success\">مَكَانً۬ا</span> <span class=\"quran-arabic-font text-success\">ضَيِّقً۬ا</span> <span class=\"quran-arabic-font text-success\">مُّقَرَّنِينَ</span> <span class=\"quran-arabic-font text-success\">دَعَوۡاْ</span> <span class=\"quran-arabic-font text-success\">هُنَالِكَ</span> <span class=\"quran-arabic-font text-success\">ثُبُورً۬ا</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(அவர்கள் சங்கிலிகளால் பிணைக்கப்பட்டு அதிலுள்ள ஒரு குறுகிய இடத்தில் தள்ளப்படும்போது, அங்கே தங்களின் அழிவிற்காகக் கதறுவார்கள்.) (<a href=\"qurandisp.php?sura=25&ayah=13\" class=\"link\">25:13</a>) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">كِتَـٰبٌ۬</span> <span class=\"quran-arabic-font text-success\">مَّرۡقُومٌ۬</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(அது எழுதப்பட்ட ஒரு பதிவேடாகும்.) இது <span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَدۡرَٮٰكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سِجِّينٌ۬</span> <span class=\"quran-arabic-font text-success\">﴾</span> (ஸிஜ்ஜீன் என்றால் என்னவென்று உமக்கு எது அறிவிக்கும்?) என்ற அவனது கூற்றின் விளக்கமல்ல. மாறாக, அவர்களுக்காகப் பதிவு செய்யப்படும் அந்த 'ஸிஜ்ஜீன்' எனும் இலக்கைப் பற்றிய விளக்கமாகும். அதாவது, அது பதிவு செய்யப்பட்டு, எழுதப்பட்டு, முடிக்கப்பட்டுவிட்டது. அதில் எவரும் எதையும் கூட்டவோ அல்லது அதிலிருந்து எதையும் நீக்கவோ முடியாது. இதனை முஹம்மது இப்னு கஅப் அல்-குரழீ கூறினார்கள். பின்னர் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَيۡلٌ۬</span> <span class=\"quran-arabic-font text-success\">يَوۡمَٮِٕذٍ۬</span> <span class=\"quran-arabic-font text-success\">لِّلۡمُكَذِّبِينَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(அந்நாளில் பொய்ப்பிப்பவர்களுக்குக் கேடுதான்.) அதாவது, மறுமை நாளில் அல்லாஹ் எச்சரித்த அந்தச் சிறைவாசம் மற்றும் இழிவான வேதனைக்கு அவர்கள் வரும்போது அவர்களுக்கு அழிவு உண்டு. 'வைல்' (கேடு) என்பது பற்றி ஏற்கனவே விளக்கப்பட்டுள்ளது, அதனை மீண்டும் இங்கு கூற வேண்டிய அவசியமில்லை. அதன் அடிப்படைப் பொருள் அழிவும் நாசமுமாகும்.<br />\r\n<br />\r\nஇது \"இன்னாருக்குக் கேடு உண்டாகட்டும்\" என்று கூறுவதைப் போன்றது. பஹ்ஸ் இப்னு ஹகீம் இப்னு முஆவியா இப்னு ஹைதா (ரழி) தனது தந்தை வழியாக, அவர் தனது பாட்டனார் வழியாக அறிவித்தது முஸ்னத் மற்றும் சுனன் நூல்களில் இடம்பெற்றுள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n« <span class=\"quran-arabic-font text-success\">وَيْلٌ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِي</span> <span class=\"quran-arabic-font text-success\">يُحَدِّثُ</span> <span class=\"quran-arabic-font text-success\">فَيَكْذِبُ</span> <span class=\"quran-arabic-font text-success\">لِيُضْحِكَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ،</span> <span class=\"quran-arabic-font text-success\">وَيْلٌ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">وَيْلٌ</span> <span class=\"quran-arabic-font text-success\">لَه</span> »<br />\r\n(மக்களைச் சிரிக்க வைப்பதற்காகப் பொய் பேசுபவனுக்குக் கேடுதான். அவனுக்குக் கேடுதான், அவனுக்குக் கேடுதான்.) பின்னர் தீய, நிராகரிக்கும் மறுப்பாளர்கள் யார் என்பதை விளக்கி அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">ٱلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُونَ</span> <span class=\"quran-arabic-font text-success\">بِيَوۡمِ</span> <span class=\"quran-arabic-font text-success\">ٱلدِّينِ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(அவர்கள் தீர்ப்பு நாளைப் பொய்ப்பிக்கிறார்கள்.) அதாவது, அது நடக்கும் என்றோ, அப்படி ஒன்று உண்டு என்றோ அவர்கள் நம்புவதில்லை. அதனை ஒரு சாத்தியமற்ற விஷயமாகக் கருதுகிறார்கள். பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُ</span> <span class=\"quran-arabic-font text-success\">بِهِۦۤ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">مُعۡتَدٍ</span> <span class=\"quran-arabic-font text-success\">أَثِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(வரம்பு மீறிய பாவி தவிர வேறு யாரும் அதனைப் பொய்ப்பிக்க மாட்டார்கள்.) அதாவது, ஹராமான காரியங்களைச் செய்வதன் மூலம் தனது செயல்களில் வரம்பு மீறுபவன்; பேசும்போது பொய் சொல்பவன், வாக்குக் கொடுத்தால் அதனை மீறுபவன், விவாதம் செய்தால் அநாகரிகமாகவும் தீய முறையிலும் நடந்து கொள்பவன். அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">تُتۡلَىٰ</span> <span class=\"quran-arabic-font text-success\">عَلَيۡهِ</span> <span class=\"quran-arabic-font text-success\">ءَايَـٰتُنَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">أَسَـٰطِيرُ</span> <span class=\"quran-arabic-font text-success\">ٱلۡأَوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(அவனிடம் நம்முடைய வசனங்கள் ஓதப்பட்டால், அவன்: \"முன்னோர்களின் கட்டுக்கதைகள்!\" எனக் கூறுகிறான்.) அதாவது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து அல்லாஹ்வின் வார்த்தைகளைக் கேட்கும் போதெல்லாம் அவன் அதனை மறுத்து, அதைப் பற்றித் தீய எண்ணம் கொள்கிறான். அது முன்னோர்களின் புத்தகங்களிலிருந்து திரட்டப்பட்ட ஒரு தொகுப்பு என அவன் நம்புகிறான். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مَّاذَآ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمۡ</span>‌<span class=\"quran-arabic-font text-success\">ۙ</span> <span class=\"quran-arabic-font text-success\">قَالُوٓاْ</span> <span class=\"quran-arabic-font text-success\">أَسَـٰطِيرُ</span> <span class=\"quran-arabic-font text-success\">ٱلۡأَوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(மேலும் அவர்களிடம், \"உமது இறைவன் எதை இறக்கினான்?\" என்று கேட்கப்பட்டால், அவர்கள் \"முன்னோர்களின் கட்டுக்கதைகள்!\" எனக் கூறுகிறார்கள்.) (<a href=\"qurandisp.php?sura=16&ayah=24\" class=\"link\">16:24</a>) இதேபோல் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">وَقَالُوٓاْ</span> <span class=\"quran-arabic-font text-success\">أَسَـٰطِيرُ</span> <span class=\"quran-arabic-font text-success\">ٱلۡأَوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">ٱڪۡتَتَبَهَا</span> <span class=\"quran-arabic-font text-success\">فَهِىَ</span> <span class=\"quran-arabic-font text-success\">تُمۡلَىٰ</span> <span class=\"quran-arabic-font text-success\">عَلَيۡهِ</span> <span class=\"quran-arabic-font text-success\">بُڪۡرَةً۬</span> <span class=\"quran-arabic-font text-success\">وَأَصِيلاً۬</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(மேலும் அவர்கள் கூறுகிறார்கள்: \"முன்னோர்களின் கட்டுக்கதைகள், அவற்றை அவர் எழுதி வைத்துள்ளார்; அவை காலையிலும் மாலையிலும் அவருக்கு ஓதிக்காட்டப்படுகின்றன.\") (<a href=\"qurandisp.php?sura=25&ayah=5\" class=\"link\">25:5</a>) பின்னர் அல்லாஹ் தொடர்ந்து கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">كَلَّا</span>‌<span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">بَلۡۜ</span> <span class=\"quran-arabic-font text-success\">رَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَىٰ</span> <span class=\"quran-arabic-font text-success\">قُلُوبِہِم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَكۡسِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(அப்படியல்ல! மாறாக, அவர்கள் சம்பாதித்தவை அவர்களின் இதயங்களின் மேல் ஒரு திரையாக (ரான்) மூடிவிட்டன.) அதாவது, அவர்கள் வாதிடுவது போலவோ அல்லது \"நிச்சயமாக இந்த குர்ஆன் முன்னோர்களின் கட்டுக்கதைகள்\" என்று அவர்கள் கூறுவது போலவோ நிலைமை இல்லை. மாறாக, இது அல்லாஹ்வின் வார்த்தை, அவனுடைய தூதர் (ஸல்) அவர்களுக்கு அருளப்பட்ட அவனது வஹீ (இறைச்செய்தி) ஆகும். அவர்கள் செய்த அடுக்கடுக்கான பாவங்களினால் ஏற்பட்ட இருண்ட திரையே அவர்களின் இதயங்கள் இதனை நம்புவதைத் தடுத்த ஒரே தடையாகும். எனவேதான் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">كَلَّا</span>‌<span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">بَلۡۜ</span> <span class=\"quran-arabic-font text-success\">رَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَىٰ</span> <span class=\"quran-arabic-font text-success\">قُلُوبِہِم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَكۡسِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(அப்படியல்ல! மாறாக, அவர்கள் சம்பாதித்தவை அவர்களின் இதயங்களின் மேல் ஒரு திரையாக (ரான்) மூடிவிட்டன.) 'ரய்ன்' எனப்படும் இந்த இருண்ட மூடி காஃபிர்களின் (நிராகரிப்பாளர்களின்) இதயங்களை ஆட்கொள்கிறது. 'கய்ம்' எனும் திரை நல்லவர்களுக்கும், 'கய்ன்' எனும் திரை அல்லாஹ்வுக்கு நெருக்கமானவர்களுக்கும் உரியது. இப்னு ஜரீர், அத்-திர்மிதி, அன்-நஸாயீ மற்றும் இப்னு மாஜா ஆகியோர் அபூ ஹுரைரா (ரழி) அறிவிப்பதாகப் பதிவு செய்துள்ளனர், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n« <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">أَذْنَبَ</span> <span class=\"quran-arabic-font text-success\">ذَنْبًا</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">نُكْتَةٌ</span> <span class=\"quran-arabic-font text-success\">سَوْدَاءُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَلْبِهِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">تَابَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">صُقِلَ</span> <span class=\"quran-arabic-font text-success\">قَلْبُهُ،</span> <span class=\"quran-arabic-font text-success\">فوَإِنْ</span> <span class=\"quran-arabic-font text-success\">زَادَ</span> <span class=\"quran-arabic-font text-success\">زَادَتْ،</span> <span class=\"quran-arabic-font text-success\">فَذلِكَ</span> <span class=\"quran-arabic-font text-success\">قَوْلُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>:<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">كَلَّا</span>‌<span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">بَلۡۜ</span> <span class=\"quran-arabic-font text-success\">رَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَىٰ</span> <span class=\"quran-arabic-font text-success\">قُلُوبِہِم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَكۡسِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(நிச்சயமாக ஒரு அடியான் ஒரு பாவத்தைச் செய்யும்போது அவனது இதயத்தில் ஒரு கரும்புள்ளி விழுகிறது. அவன் அதற்காகத் தவ்பா (பாவமன்னிப்பு) தேடினால் அவனது இதயம் தூய்மையாக்கப்படுகிறது. ஆனால் அவன் பாவத்தை அதிகரித்தால் அந்தக் கரும்புள்ளியும் அதிகரித்துக் கொண்டே போகும். அதுவே அல்லாஹ்வின் இந்தக் கூற்றாகும்: ((அப்படியல்ல! மாறாக, அவர்கள் சம்பாதித்தவை அவர்களின் இதயங்களின் மேல் ஒரு திரையாக (ரான்) மூடிவிட்டன.))) அத்-திர்மிதி இதனை 'ஹஸன் ஸஹீஹ்' எனக் குறிப்பிட்டுள்ளார். அன்-நஸாயீயின் அறிவிப்பில் பின்வருமாறு உள்ளது:<br />\r\n<br />\r\n« <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">أَخْطَأَ</span> <span class=\"quran-arabic-font text-success\">خَطِيئَةً</span> <span class=\"quran-arabic-font text-success\">نُكِتَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَلْبِهِ</span> <span class=\"quran-arabic-font text-success\">نُكْتَةٌ</span> <span class=\"quran-arabic-font text-success\">سَوْدَاءُ</span> <span class=\"quran-arabic-font text-success\">،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">نَزَعَ</span> <span class=\"quran-arabic-font text-success\">وَاسْتَغْفَرَ</span> <span class=\"quran-arabic-font text-success\">وَتَابَ</span> <span class=\"quran-arabic-font text-success\">صُقِلَ</span> <span class=\"quran-arabic-font text-success\">قَلْبُهُ</span> <span class=\"quran-arabic-font text-success\">،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">عَادَ</span> <span class=\"quran-arabic-font text-success\">زِيدَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَعْلُو</span> <span class=\"quran-arabic-font text-success\">قَلْبَهُ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">الرَّانُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>:<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">كَلَّا</span>‌<span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">بَلۡۜ</span> <span class=\"quran-arabic-font text-success\">رَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَىٰ</span> <span class=\"quran-arabic-font text-success\">قُلُوبِہِم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَكۡسِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(நிச்சயமாக ஒரு அடியான் ஒரு தவறு செய்யும்போது அவனது இதயத்தில் ஒரு கரும்புள்ளி இடப்படுகிறது. அவன் அதிலிருந்து விலகி, மன்னிப்புக் கோரி, பாவமன்னிப்புத் தேடினால் அவனது இதயம் சுத்தப்படுத்தப்படுகிறது. ஆனால் அவன் மீண்டும் பாவத்தைச் செய்தால், அது அவனது (முழு) இதயத்தையும் ஆட்கொள்ளும் வரை அதிகரித்துக் கொண்டே செல்லும். இதுதான் அல்லாஹ் குறிப்பிடும் 'ரான்' ஆகும். அவன் கூறுகிறான்: (அப்படியல்ல! மாறாக, அவர்கள் சம்பாதித்தவை அவர்களின் இதயங்களின் மேல் ஒரு திரையாக (ரான்) மூடிவிட்டன.)) அல்-ஹஸன் அல்-பஸ்ரி அவர்கள் கூறினார்கள்: “இது, இதயம் குருடாகி இறந்துவிடும் வரை, பாவத்தின் மீது பாவம் செய்வதாகும்.” அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">كَلَّآ</span> <span class=\"quran-arabic-font text-success\">إِنَّہُمۡ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">رَّبِّہِمۡ</span> <span class=\"quran-arabic-font text-success\">يَوۡمَٮِٕذٍ۬</span> <span class=\"quran-arabic-font text-success\">لَّمَحۡجُوبُونَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(நிச்சயமாக, அவர்கள் அந்நாளில் தங்கள் இறைவனைப் பார்ப்பதிலிருந்து திரையிடப்படுவார்கள்.) அதாவது, மறுமை நாளில் அவர்களுக்கு ஒரு இடம் இருக்கும், அவர்கள் ஸிஜ்ஜீனில் தங்குவார்கள். அதனுடன் சேர்த்து, மறுமை நாளில் தங்களின் இறைவனையும் படைப்பாளனையும் தரிசிப்பதிலிருந்து அவர்கள் திரையிடப்பட்டுத் தடுக்கப்படுவார்கள். இமாம் அபூ அப்துல்லாஹ் அஷ்-ஷாஃபிஈ அவர்கள் கூறினார்கள்: \"இந்த வசனம், முஃமின்கள் (நம்பிக்கையாளர்கள்) கண்ணியமிக்க மேலான அல்லாஹ்வை அந்நாளில் காண்பார்கள் என்பதற்கு ஒரு ஆதாரமாகும்.\" அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّہُمۡ</span> <span class=\"quran-arabic-font text-success\">لَصَالُواْ</span> <span class=\"quran-arabic-font text-success\">ٱلۡجَحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(பின்னர் நிச்சயமாக, அவர்கள் நரகத்தின் கொழுந்துவிட்டெரியும் நெருப்பில் நுழைவார்கள்.) அதாவது, அளவற்ற அருளாளனைப் பார்ப்பதிலிருந்து தடுக்கப்படுவதோடு, அவர்கள் நரகவாசிகளாகவும் இருப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُقَالُ</span> <span class=\"quran-arabic-font text-success\">هَـٰذَا</span> <span class=\"quran-arabic-font text-success\">ٱلَّذِى</span> <span class=\"quran-arabic-font text-success\">كُنتُم</span> <span class=\"quran-arabic-font text-success\">بِهِۦ</span> <span class=\"quran-arabic-font text-success\">تُكَذِّبُونَ</span> <span class=\"quran-arabic-font text-success\">﴾</span><br />\r\n(பின்னர் அவர்களுக்குக் கூறப்படும்: \"நீங்கள் எதனைப் பொய்ப்பித்துக் கொண்டிருந்தீர்களோ அது இதுதான்!\") (<a href=\"qurandisp.php?sura=83&ayah=17\" class=\"link\">83:17</a>) அதாவது, அவர்களைக் கண்டிக்கும் விதமாகவும், சிறுமைப்படுத்தும் மற்றும் அவமானப்படுத்தும் விதமாகவும் இது அவர்களுக்குச் சொல்லப்படும்.<br />\r\n<br />","text":"தீயோரின் பதிவேடும், அவர்களுக்கு நேரிடுபவை பற்றியும்\n\r\n\n\r\nஅல்லாஹ் உண்மையாகவே கூறுகிறான்,\n\r\n\n\r\n﴿ إِنَّ كِتَـٰبَ ٱلۡفُجَّارِ لَفِى سِجِّينٍ۬ ﴾\n\r\n(இல்லை! நிச்சயமாகத் தீயோரின் பதிவேடு ஸிஜ்ஜீனில் இருக்கிறது.) அதாவது, அவர்களின் இறுதி இலக்கும் தங்குமிடமும் ஸிஜ்ஜீனில் இருக்கும். இது சிறை (ஸிஜ்ன்) என்ற சொல்லில் இருந்து உருவானதாகும், இங்கு இது நெருக்கடியான சூழலைக் குறிக்கிறது. இந்த விஷயத்தின் பாரதூரத்தை உணர்த்த அல்லாஹ் கூறுகிறான்;\n\r\n\n\r\n﴿ وَمَآ أَدۡرَٮٰكَ مَا سِجِّينٌ۬ ﴾\n\r\n(ஸிஜ்ஜீன் என்றால் என்னவென்று உமக்கு எது அறிவிக்கும்?) அதாவது, அது ஒரு பாரிய விஷயம், நிரந்தரச் சிறை மற்றும் வலிமிகுந்த வேதனையாகும். இது ஏழாவது பூமிக்குக் கீழே இருப்பதாகச் சிலர் கூறியுள்ளனர். அல்-பரா இப்னு ஆஸிப் (ரழி) அவர்களின் நீண்ட ஹதீஸில், நபி (ஸல்) அவர்கள் பின்வருமாறு கூறியதாக முன்னரே குறிப்பிடப்பட்டுள்ளது:\n\r\n\n\r\n« يَقُول اللهُ عَزَّ وَجَلَّ فِي رُوحِ الْكَافِرِ اكْتُبُوا كِتَابَهُ فِي سِجِّينٍ. وَسِجِّينٌ هِيَ تَحْتُ الْأَرْضِ السَّابِعَة »\n\r\n(அல்லாஹ் ஒரு காஃபிரின் (நிராகரிப்பாளனின்) ஆன்மாவைப் பற்றிக் கூறும்போது, 'அவனது பதிவேட்டை ஸிஜ்ஜீனில் பதிவு செய்யுங்கள்' என்று கூறுவான். ஸிஜ்ஜீன் என்பது ஏழாவது பூமிக்குக் கீழே உள்ளதாகும்.) தீயவர்களின் தங்குமிடம் நரகமாகும் என்பது அனைவரும் அறிந்ததே. அது தாழ்ந்தவற்றில் மிகவும் தாழ்ந்த இடமாகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴿ ثُمَّ رَدَدۡنَـٰهُ أَسۡفَلَ سَـٰفِلِينَ • إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَـٰتِ ﴾\n\r\n(பின்னர் நாம் அவனைத் தாழ்ந்தவர்களில் மிகத் தாழ்ந்தவனாக ஆக்கினோம். ஈமான் (நம்பிக்கை) கொண்டு நற்செயல்கள் செய்தவர்களைத் தவிர.) (95:5-6) அல்லாஹ் இங்கு கூறுகிறான்:\n\r\n\n\r\n﴿ كَلَّآ إِنَّ كِتَـٰبَ ٱلۡفُجَّارِ لَفِى سِجِّينٍ۬ • وَمَآ أَدۡرَٮٰكَ مَا سِجِّينٌ۬ ﴾\n\r\n(இல்லை! நிச்சயமாகத் தீயோரின் பதிவேடு ஸிஜ்ஜீனில் இருக்கிறது. ஸிஜ்ஜீன் என்றால் என்னவென்று உமக்கு எது அறிவிக்கும்?) அது துன்பமும் துயரமும் நிறைந்ததாகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴿ وَإِذَآ أُلۡقُواْ مِنۡہَا مَكَانً۬ا ضَيِّقً۬ا مُّقَرَّنِينَ دَعَوۡاْ هُنَالِكَ ثُبُورً۬ا ﴾\n\r\n(அவர்கள் சங்கிலிகளால் பிணைக்கப்பட்டு அதிலுள்ள ஒரு குறுகிய இடத்தில் தள்ளப்படும்போது, அங்கே தங்களின் அழிவிற்காகக் கதறுவார்கள்.) (25:13) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴿ كِتَـٰبٌ۬ مَّرۡقُومٌ۬ ﴾\n\r\n(அது எழுதப்பட்ட ஒரு பதிவேடாகும்.) இது ﴿ وَمَآ أَدۡرَٮٰكَ مَا سِجِّينٌ۬ ﴾ (ஸிஜ்ஜீன் என்றால் என்னவென்று உமக்கு எது அறிவிக்கும்?) என்ற அவனது கூற்றின் விளக்கமல்ல. மாறாக, அவர்களுக்காகப் பதிவு செய்யப்படும் அந்த 'ஸிஜ்ஜீன்' எனும் இலக்கைப் பற்றிய விளக்கமாகும். அதாவது, அது பதிவு செய்யப்பட்டு, எழுதப்பட்டு, முடிக்கப்பட்டுவிட்டது. அதில் எவரும் எதையும் கூட்டவோ அல்லது அதிலிருந்து எதையும் நீக்கவோ முடியாது. இதனை முஹம்மது இப்னு கஅப் அல்-குரழீ கூறினார்கள். பின்னர் அல்லாஹ் கூறினான்:\n\r\n\n\r\n﴿ وَيۡلٌ۬ يَوۡمَٮِٕذٍ۬ لِّلۡمُكَذِّبِينَ ﴾\n\r\n(அந்நாளில் பொய்ப்பிப்பவர்களுக்குக் கேடுதான்.) அதாவது, மறுமை நாளில் அல்லாஹ் எச்சரித்த அந்தச் சிறைவாசம் மற்றும் இழிவான வேதனைக்கு அவர்கள் வரும்போது அவர்களுக்கு அழிவு உண்டு. 'வைல்' (கேடு) என்பது பற்றி ஏற்கனவே விளக்கப்பட்டுள்ளது, அதனை மீண்டும் இங்கு கூற வேண்டிய அவசியமில்லை. அதன் அடிப்படைப் பொருள் அழிவும் நாசமுமாகும்.\n\r\n\n\r\nஇது \"இன்னாருக்குக் கேடு உண்டாகட்டும்\" என்று கூறுவதைப் போன்றது. பஹ்ஸ் இப்னு ஹகீம் இப்னு முஆவியா இப்னு ஹைதா (ரழி) தனது தந்தை வழியாக, அவர் தனது பாட்டனார் வழியாக அறிவித்தது முஸ்னத் மற்றும் சுனன் நூல்களில் இடம்பெற்றுள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n« وَيْلٌ لِلَّذِي يُحَدِّثُ فَيَكْذِبُ لِيُضْحِكَ النَّاسَ، وَيْلٌ لَهُ وَيْلٌ لَه »\n\r\n(மக்களைச் சிரிக்க வைப்பதற்காகப் பொய் பேசுபவனுக்குக் கேடுதான். அவனுக்குக் கேடுதான், அவனுக்குக் கேடுதான்.) பின்னர் தீய, நிராகரிக்கும் மறுப்பாளர்கள் யார் என்பதை விளக்கி அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴿ ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ ﴾\n\r\n(அவர்கள் தீர்ப்பு நாளைப் பொய்ப்பிக்கிறார்கள்.) அதாவது, அது நடக்கும் என்றோ, அப்படி ஒன்று உண்டு என்றோ அவர்கள் நம்புவதில்லை. அதனை ஒரு சாத்தியமற்ற விஷயமாகக் கருதுகிறார்கள். பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴿ وَمَا يُكَذِّبُ بِهِۦۤ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ ﴾\n\r\n(வரம்பு மீறிய பாவி தவிர வேறு யாரும் அதனைப் பொய்ப்பிக்க மாட்டார்கள்.) அதாவது, ஹராமான காரியங்களைச் செய்வதன் மூலம் தனது செயல்களில் வரம்பு மீறுபவன்; பேசும்போது பொய் சொல்பவன், வாக்குக் கொடுத்தால் அதனை மீறுபவன், விவாதம் செய்தால் அநாகரிகமாகவும் தீய முறையிலும் நடந்து கொள்பவன். அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை:\n\r\n\n\r\n﴿ إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلۡأَوَّلِينَ ﴾\n\r\n(அவனிடம் நம்முடைய வசனங்கள் ஓதப்பட்டால், அவன்: \"முன்னோர்களின் கட்டுக்கதைகள்!\" எனக் கூறுகிறான்.) அதாவது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து அல்லாஹ்வின் வார்த்தைகளைக் கேட்கும் போதெல்லாம் அவன் அதனை மறுத்து, அதைப் பற்றித் தீய எண்ணம் கொள்கிறான். அது முன்னோர்களின் புத்தகங்களிலிருந்து திரட்டப்பட்ட ஒரு தொகுப்பு என அவன் நம்புகிறான். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\n﴿ وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمۡ‌ۙ قَالُوٓاْ أَسَـٰطِيرُ ٱلۡأَوَّلِينَ ﴾\n\r\n(மேலும் அவர்களிடம், \"உமது இறைவன் எதை இறக்கினான்?\" என்று கேட்கப்பட்டால், அவர்கள் \"முன்னோர்களின் கட்டுக்கதைகள்!\" எனக் கூறுகிறார்கள்.) (16:24) இதேபோல் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴿ وَقَالُوٓاْ أَسَـٰطِيرُ ٱلۡأَوَّلِينَ ٱڪۡتَتَبَهَا فَهِىَ تُمۡلَىٰ عَلَيۡهِ بُڪۡرَةً۬ وَأَصِيلاً۬ ﴾\n\r\n(மேலும் அவர்கள் கூறுகிறார்கள்: \"முன்னோர்களின் கட்டுக்கதைகள், அவற்றை அவர் எழுதி வைத்துள்ளார்; அவை காலையிலும் மாலையிலும் அவருக்கு ஓதிக்காட்டப்படுகின்றன.\") (25:5) பின்னர் அல்லாஹ் தொடர்ந்து கூறுகிறான்:\n\r\n\n\r\n﴿ كَلَّا‌ۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِہِم مَّا كَانُواْ يَكۡسِبُونَ ﴾\n\r\n(அப்படியல்ல! மாறாக, அவர்கள் சம்பாதித்தவை அவர்களின் இதயங்களின் மேல் ஒரு திரையாக (ரான்) மூடிவிட்டன.) அதாவது, அவர்கள் வாதிடுவது போலவோ அல்லது \"நிச்சயமாக இந்த குர்ஆன் முன்னோர்களின் கட்டுக்கதைகள்\" என்று அவர்கள் கூறுவது போலவோ நிலைமை இல்லை. மாறாக, இது அல்லாஹ்வின் வார்த்தை, அவனுடைய தூதர் (ஸல்) அவர்களுக்கு அருளப்பட்ட அவனது வஹீ (இறைச்செய்தி) ஆகும். அவர்கள் செய்த அடுக்கடுக்கான பாவங்களினால் ஏற்பட்ட இருண்ட திரையே அவர்களின் இதயங்கள் இதனை நம்புவதைத் தடுத்த ஒரே தடையாகும். எனவேதான் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴿ كَلَّا‌ۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِہِم مَّا كَانُواْ يَكۡسِبُونَ ﴾\n\r\n(அப்படியல்ல! மாறாக, அவர்கள் சம்பாதித்தவை அவர்களின் இதயங்களின் மேல் ஒரு திரையாக (ரான்) மூடிவிட்டன.) 'ரய்ன்' எனப்படும் இந்த இருண்ட மூடி காஃபிர்களின் (நிராகரிப்பாளர்களின்) இதயங்களை ஆட்கொள்கிறது. 'கய்ம்' எனும் திரை நல்லவர்களுக்கும், 'கய்ன்' எனும் திரை அல்லாஹ்வுக்கு நெருக்கமானவர்களுக்கும் உரியது. இப்னு ஜரீர், அத்-திர்மிதி, அன்-நஸாயீ மற்றும் இப்னு மாஜா ஆகியோர் அபூ ஹுரைரா (ரழி) அறிவிப்பதாகப் பதிவு செய்துள்ளனர், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n« إِنَّ الْعَبْدَ إِذَا أَذْنَبَ ذَنْبًا كَانَتْ نُكْتَةٌ سَوْدَاءُ فِي قَلْبِهِ، فَإِنْ تَابَ مِنْهَا صُقِلَ قَلْبُهُ، فوَإِنْ زَادَ زَادَتْ، فَذلِكَ قَوْلُ اللهِ تَعَالَى:\n\r\n﴿ كَلَّا‌ۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِہِم مَّا كَانُواْ يَكۡسِبُونَ ﴾\n\r\n(நிச்சயமாக ஒரு அடியான் ஒரு பாவத்தைச் செய்யும்போது அவனது இதயத்தில் ஒரு கரும்புள்ளி விழுகிறது. அவன் அதற்காகத் தவ்பா (பாவமன்னிப்பு) தேடினால் அவனது இதயம் தூய்மையாக்கப்படுகிறது. ஆனால் அவன் பாவத்தை அதிகரித்தால் அந்தக் கரும்புள்ளியும் அதிகரித்துக் கொண்டே போகும். அதுவே அல்லாஹ்வின் இந்தக் கூற்றாகும்: ((அப்படியல்ல! மாறாக, அவர்கள் சம்பாதித்தவை அவர்களின் இதயங்களின் மேல் ஒரு திரையாக (ரான்) மூடிவிட்டன.))) அத்-திர்மிதி இதனை 'ஹஸன் ஸஹீஹ்' எனக் குறிப்பிட்டுள்ளார். அன்-நஸாயீயின் அறிவிப்பில் பின்வருமாறு உள்ளது:\n\r\n\n\r\n« إِنَّ الْعَبْدَ إِذَا أَخْطَأَ خَطِيئَةً نُكِتَ فِي قَلْبِهِ نُكْتَةٌ سَوْدَاءُ ، فَإِنْ هُوَ نَزَعَ وَاسْتَغْفَرَ وَتَابَ صُقِلَ قَلْبُهُ ، فَإِنْ عَادَ زِيدَ فِيهَا حَتَّى تَعْلُو قَلْبَهُ فَهُوَ الرَّانُ الَّذِي قَالَ اللهُ تَعَالَى:\n\r\n﴿ كَلَّا‌ۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِہِم مَّا كَانُواْ يَكۡسِبُونَ ﴾\n\r\n(நிச்சயமாக ஒரு அடியான் ஒரு தவறு செய்யும்போது அவனது இதயத்தில் ஒரு கரும்புள்ளி இடப்படுகிறது. அவன் அதிலிருந்து விலகி, மன்னிப்புக் கோரி, பாவமன்னிப்புத் தேடினால் அவனது இதயம் சுத்தப்படுத்தப்படுகிறது. ஆனால் அவன் மீண்டும் பாவத்தைச் செய்தால், அது அவனது (முழு) இதயத்தையும் ஆட்கொள்ளும் வரை அதிகரித்துக் கொண்டே செல்லும். இதுதான் அல்லாஹ் குறிப்பிடும் 'ரான்' ஆகும். அவன் கூறுகிறான்: (அப்படியல்ல! மாறாக, அவர்கள் சம்பாதித்தவை அவர்களின் இதயங்களின் மேல் ஒரு திரையாக (ரான்) மூடிவிட்டன.)) அல்-ஹஸன் அல்-பஸ்ரி அவர்கள் கூறினார்கள்: “இது, இதயம் குருடாகி இறந்துவிடும் வரை, பாவத்தின் மீது பாவம் செய்வதாகும்.” அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை:\n\r\n\n\r\n﴿ كَلَّآ إِنَّہُمۡ عَن رَّبِّہِمۡ يَوۡمَٮِٕذٍ۬ لَّمَحۡجُوبُونَ ﴾\n\r\n(நிச்சயமாக, அவர்கள் அந்நாளில் தங்கள் இறைவனைப் பார்ப்பதிலிருந்து திரையிடப்படுவார்கள்.) அதாவது, மறுமை நாளில் அவர்களுக்கு ஒரு இடம் இருக்கும், அவர்கள் ஸிஜ்ஜீனில் தங்குவார்கள். அதனுடன் சேர்த்து, மறுமை நாளில் தங்களின் இறைவனையும் படைப்பாளனையும் தரிசிப்பதிலிருந்து அவர்கள் திரையிடப்பட்டுத் தடுக்கப்படுவார்கள். இமாம் அபூ அப்துல்லாஹ் அஷ்-ஷாஃபிஈ அவர்கள் கூறினார்கள்: \"இந்த வசனம், முஃமின்கள் (நம்பிக்கையாளர்கள்) கண்ணியமிக்க மேலான அல்லாஹ்வை அந்நாளில் காண்பார்கள் என்பதற்கு ஒரு ஆதாரமாகும்.\" அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை:\n\r\n\n\r\n﴿ ثُمَّ إِنَّہُمۡ لَصَالُواْ ٱلۡجَحِيمِ ﴾\n\r\n(பின்னர் நிச்சயமாக, அவர்கள் நரகத்தின் கொழுந்துவிட்டெரியும் நெருப்பில் நுழைவார்கள்.) அதாவது, அளவற்ற அருளாளனைப் பார்ப்பதிலிருந்து தடுக்கப்படுவதோடு, அவர்கள் நரகவாசிகளாகவும் இருப்பார்கள்.\n\r\n\n\r\n﴿ ثُمَّ يُقَالُ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ ﴾\n\r\n(பின்னர் அவர்களுக்குக் கூறப்படும்: \"நீங்கள் எதனைப் பொய்ப்பித்துக் கொண்டிருந்தீர்களோ அது இதுதான்!\") (83:17) அதாவது, அவர்களைக் கண்டிக்கும் விதமாகவும், சிறுமைப்படுத்தும் மற்றும் அவமானப்படுத்தும் விதமாகவும் இது அவர்களுக்குச் சொல்லப்படும்."},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=28\" class=\"link\">83:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:28 ஐ பார்க்கவும்"},"28":{"html":"<strong>நல்லோர்களின் பதிவுப் புத்தகமும் அவர்களுக்கான நற்கூலியும்</strong><br />\r\n<br />\r\nநிச்சயமாக, <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">كِتَابَ</span> <span class=\"quran-arabic-font text-success\">الْأَبْرَارِ﴿</span> (நிச்சயமாக அப்ரார் -நல்லோர்களின்- பதிவுப் புத்தகம்) என்று அல்லாஹ் கூறுகிறான். இவர்கள் தீயவர்களுக்கு நேர்மாறான நிலையில் இருக்கிறார்கள். <span class=\"quran-arabic-font text-success\">﴾لَفِي</span> <span class=\"quran-arabic-font text-success\">عِلِّيِّينَ﴿</span> (`இல்லிய்யீனில் இருக்கிறது.) அதாவது, அவர்களின் இறுதி சேருமிடம் `இல்லிய்யீன் ஆகும்; இது ஸிஜ்ஜீன் என்பதற்கு நேர்மாறானது.<br />\r\n<br />\r\nஹிலால் பின் யஸாஃப் அறிவிப்பதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள், கஅப் (ரழி) அவர்களிடம் ஸிஜ்ஜீன் பற்றி வினவியபோது, \"அது ஏழாவது பூமியாகும், அதில் நிராகரிப்பாளர்களின் ஆன்மாக்கள் உள்ளன\" என்று கஅப் (ரழி) அவர்கள் கூறினார்கள். பிறகு இப்னு அப்பாஸ் (ரழி) அவர்கள் அவரிடம் `இல்லிய்யீன் பற்றி கேட்டபோது, \"அது ஏழாவது வானமாகும், அதில் முஃமின்களின் ஆன்மாக்கள் உள்ளன\" என்று பதிலளித்தார்கள்.<br />\r\n<br />\r\nஅது ஏழாவது வானம் என்ற இந்தக் கூற்றை மற்றவர்களும் கூறியுள்ளனர். <span class=\"quran-arabic-font text-success\">﴾كَلَّا</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">كِتَابَ</span> <span class=\"quran-arabic-font text-success\">الْأَبْرَارِ</span> <span class=\"quran-arabic-font text-success\">لَفِي</span> <span class=\"quran-arabic-font text-success\">عِلِّيِّينَ﴿</span> (அப்படியல்ல! நிச்சயமாக நல்லோர்களின் பதிவுப் புத்தகம் `இல்லிய்யீனில் இருக்கிறது.) என்ற அல்லாஹ்வின் வசனம் குறித்து அலி பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிப்பதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் சுவனமாகும்\" என்று கூறினார்கள். இது 'ஸித்ரத்துல் முன்தஹா'வில் அமைந்துள்ளது என்று இவர்களைத் தவிர பிற அறிஞர்களும் கூறியுள்ளனர்.<br />\r\n<br />\r\n`இல்லிய்யீன்' என்ற சொல் 'உலுவ்' (உயர்வு) என்ற சொல்லிலிருந்து பெறப்பட்டது என்பது வெளிப்படையான பொருளாகும். ஒரு விஷயம் எந்தளவுக்கு உயர்ந்து மேலோங்குகிறதோ, அந்தளவுக்கு அது மகத்தானதாகவும் மேன்மையானதாகவும் மாறுகிறது. எனவேதான், அல்லாஹ் <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">أَدْرَاكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عِلِّيُّونَ﴿</span> (`இல்லிய்யீன்' என்றால் என்னவென்று உமக்கு எது அறிவிக்கும்?) என்று கூறி அதன் மகத்துவத்தை உயர்த்திக் காட்டுகிறான்.<br />\r\n<br />\r\nபின்னர், அவர்களுக்கு எழுதப்படுவதை உறுதிப்படுத்தும் விதமாக அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾كِتَابٌ</span> <span class=\"quran-arabic-font text-success\">مَّرْقُومٌ</span> * <span class=\"quran-arabic-font text-success\">يَشْهَدُهُ</span> <span class=\"quran-arabic-font text-success\">الْمُقَرَّبُونَ﴿</span> ((அது) எழுதப்பட்ட ஒரு பதிவாகும். (அல்லாஹ்விடம்) நெருக்கமானவர்கள் அதற்குச் சாட்சியாக இருப்பார்கள்.) அவர்கள் வானவர்கள் என்று கத்தாதா (ரழி) அவர்கள் கூறியுள்ளார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள், \"ஒவ்வொரு வானத்திலும் அல்லாஹ்வுக்கு மிக நெருக்கமானவர்கள் அதனை நேரில் காண்பார்கள்\" என்று கூறியதாக அல்-அவ்ஃபீ (ரழி) அறிவிக்கிறார்கள்.<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْأَبْرَارَ</span> <span class=\"quran-arabic-font text-success\">لَفِي</span> <span class=\"quran-arabic-font text-success\">نَعِيمٍ﴿</span> (நிச்சயமாக நல்லோர்கள் பேரின்பத்தில் இருப்பார்கள்.) அதாவது, மறுமை நாளில் அவர்கள் நிலையான இன்பத்திலும், அனைத்து விதமான அருட்கொடைகளையும் கொண்ட சொர்க்கச் சோலைகளிலும் இருப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَرَائِكِ﴿</span> (உயர்ந்த ஆசனங்களின் மீது,) இவை விதானங்களுக்குக் கீழே அமைக்கப்பட்டிருக்கும் ஆசனங்களாகும், அவற்றின் மீது அமர்ந்து கொண்டு அவர்கள் பார்த்துக் கொண்டிருப்பார்கள். \"இதன் பொருள், அவர்கள் தங்களது ஆட்சிப் பரப்பையும், அல்லாஹ் தங்களுக்கு வழங்கியுள்ள முடிவில்லாத, அழியாத அருட்கொடைகளையும் பார்த்துக் கொண்டிருப்பார்கள்\" என்று கூறப்படுகிறது. மேலும், <span class=\"quran-arabic-font text-success\">﴾عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَرَائِكِ</span> <span class=\"quran-arabic-font text-success\">يَنظُرُونَ﴿</span> (ஆசனங்களின் மீது அமர்ந்து பார்த்துக் கொண்டிருப்பார்கள்) என்பதற்கு \"அவர்கள் கண்ணியமும் வல்லமையும் மிக்க அல்லாஹ்வைப் பார்த்துக் கொண்டிருப்பார்கள்\" என்றும் விளக்கம் அளிக்கப்பட்டுள்ளது.<br />\r\n<br />\r\nஇது தீயவர்களைப் பற்றிக் கூறப்பட்டதற்கு நேர்மாறானதாகும்: <span class=\"quran-arabic-font text-success\">﴾كَلَّا</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">لَّمَحْجُوبُونَ﴿</span> (அப்படியல்ல! நிச்சயமாக அவர்கள் அந்நாளில் தங்கள் இறைவனைப் பார்க்க முடியாமல் திரையிடப்படுவார்கள். -<a href=\"qurandisp.php?sura=83&ayah=15\" class=\"link\">83:15</a>). எனவே, இந்த நல்லோர்கள் தங்களது உயர்ந்த ஆசனங்களிலும் மஞ்சங்களிலும் அமர்ந்திருக்கும் நிலையில், அல்லாஹ்வைத் தரிசிக்க அனுமதிக்கப்படுவார்கள் என்று குறிப்பிடப்பட்டுள்ளது.<br />\r\n<br />\r\nஅல்லாஹ்வின் வசனமான <span class=\"quran-arabic-font text-success\">﴾تَعْرِفُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">نَضْرَةَ</span> <span class=\"quran-arabic-font text-success\">النَّعِيمِ﴿</span> (அவர்களுடைய முகங்களில் இன்பத்தின் பொலிவை நீர் அறிவீர்) என்பதன் பொருள்: 'நீர் அவர்களைப் பார்க்கும்போது, அவர்களது முகங்களில் இன்பத்தின் பிரகாசத்தைக் காண்பீர்'. அந்தப் பேரின்பத்தின் காரணமாக அவர்கள் அனுபவிக்கும் செழிப்பு, கண்ணியம், மகிழ்ச்சி, மனநிறைவு மற்றும் அதிகாரம் ஆகியவற்றையே இது வர்ணிக்கிறது.<br />\r\n<br />\r\nஅல்லாஹ்வின் வசனமான <span class=\"quran-arabic-font text-success\">﴾يُسْقَوْنَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّحِيقٍ</span> <span class=\"quran-arabic-font text-success\">مَّخْتُومٍ﴿</span> (முத்திரையிடப்பட்ட தூய்மையான பானத்திலிருந்து அவர்கள் புகட்டப்படுவார்கள்) என்பது, அவர்கள் சொர்க்கத்தின் மதுவை அருந்துவார்கள் என்பதைக் குறிக்கிறது. 'அர்-ரஹீக்' என்பது சொர்க்கத்து மதுவின் பெயர்களில் ஒன்றாகும் என்று இப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரழி), அல்-ஹஸன் (ரழி), கத்தாதா (ரழி) மற்றும் இப்னு ஸைத் (ரழி) ஆகியோர் கூறியுள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾خِتَامُهُ</span> <span class=\"quran-arabic-font text-success\">مِسْكٌ﴿</span> (அதன் முத்திரை கஸ்தூரியாகும்) என்ற வசனத்தைப் பற்றி இப்னு மஸ்ஊத் (ரழி) அவர்கள், \"இதன் பொருள், அது கஸ்தூரியுடன் கலக்கப்பட்டிருக்கும்\" என்று கூறினார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அல்-அவ்ஃபீ (ரழி) அறிவிக்கிறார்கள்: \"அல்லாஹ் அந்த மதுவை நறுமணம் மிக்கதாக ஆக்குவான்; அவன் அதில் இறுதியாகச் சேர்க்கும் பொருள் கஸ்தூரியாக இருக்கும். எனவேதான் அது கஸ்தூரியால் முத்திரையிடப்படும்.\" கத்தாதா (ரழி) அவர்களும் அத்-தஹ்ஹாக் (ரழி) அவர்களும் இதையே கூறியுள்ளனர்.<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَفِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">فَلْيَتَنَافَسِ</span> <span class=\"quran-arabic-font text-success\">الْمُتَنَافِسُونَ﴿</span> (மேலும் இதற்காகவே போட்டியிடுபவர்கள் போட்டியிடட்டும்.) அதாவது, இத்தகைய நிலையை அடைவதற்காக, போட்டியிடுபவர்கள் போட்டியிடட்டும், மேலும் அதிகமாகப் பெறுவதற்கு முயற்சி செய்யட்டும். இத்தகைய பாக்கியங்களை நோக்கியே போட்டியாளர்கள் ஒருவருக்கொருவர் முந்திச் செல்ல வேண்டும். இது அல்லாஹ்வின் மற்றொரு வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾لِمِثْلِ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">فَلْيَعْمَلِ</span> <span class=\"quran-arabic-font text-success\">الْعَامِلُونَ﴿</span> (செயல்படுபவர்கள் இத்தகையவற்றிற்காகவே செயல்படட்டும் - <a href=\"qurandisp.php?sura=37&ayah=61\" class=\"link\">37:61</a>).<br />\r\n<br />\r\nஅல்லாஹ் மேலும் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمِزَاجُهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَسْنِيمٍ﴿</span> (அதன் கலவை 'தஸ்னீம்' என்பதாகும்.) அதாவது, இங்கு விவரிக்கப்படும் மது தஸ்னீமுடன் கலக்கப்பட்டுள்ளது. 'தஸ்னீம்' என்பது சொர்க்கவாசிகளின் பானங்களிலேயே மிகச் சிறந்ததும் உயர்ந்ததுமான ஒரு பானமாகும். இதனை அபூ ஸாலிஹ் (ரழி) அவர்களும் அத்-தஹ்ஹாக் (ரழி) அவர்களும் கூறியுள்ளனர்.<br />\r\n<br />\r\nஎனவேதான் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾عَيْنًا</span> <span class=\"quran-arabic-font text-success\">يَشْرَبُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">الْمُقَرَّبُونَ﴿</span> ((அது) ஒரு நீரூற்றாகும்; அதிலிருந்து அல்லாஹ்வுக்கு நெருக்கமானவர்கள் அருந்துவார்கள் - <a href=\"qurandisp.php?sura=83&ayah=28\" class=\"link\">83:28</a>). அதாவது, அல்லாஹ்வுக்கு நெருக்கமானவர்கள் அதிலிருந்து கலப்படமின்றி அருந்துவார்கள்; மேலும் வலப்பக்கத் தோழர்களுக்கு (அஸ்ஹாபுல் யமீன்) அத்துடன் கலக்கப்பட்ட பானம் வழங்கப்படும். இதனை இப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), மஸ்ரூக் (ரழி), கத்தாதா (ரழி) மற்றும் பலர் கூறியுள்ளனர்.<br />\r\n<br />","text":"நல்லோர்களின் பதிவுப் புத்தகமும் அவர்களுக்கான நற்கூலியும்\n\r\n\n\r\nநிச்சயமாக, ﴾إِنَّ كِتَابَ الْأَبْرَارِ﴿ (நிச்சயமாக அப்ரார் -நல்லோர்களின்- பதிவுப் புத்தகம்) என்று அல்லாஹ் கூறுகிறான். இவர்கள் தீயவர்களுக்கு நேர்மாறான நிலையில் இருக்கிறார்கள். ﴾لَفِي عِلِّيِّينَ﴿ (`இல்லிய்யீனில் இருக்கிறது.) அதாவது, அவர்களின் இறுதி சேருமிடம் `இல்லிய்யீன் ஆகும்; இது ஸிஜ்ஜீன் என்பதற்கு நேர்மாறானது.\n\r\n\n\r\nஹிலால் பின் யஸாஃப் அறிவிப்பதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள், கஅப் (ரழி) அவர்களிடம் ஸிஜ்ஜீன் பற்றி வினவியபோது, \"அது ஏழாவது பூமியாகும், அதில் நிராகரிப்பாளர்களின் ஆன்மாக்கள் உள்ளன\" என்று கஅப் (ரழி) அவர்கள் கூறினார்கள். பிறகு இப்னு அப்பாஸ் (ரழி) அவர்கள் அவரிடம் `இல்லிய்யீன் பற்றி கேட்டபோது, \"அது ஏழாவது வானமாகும், அதில் முஃமின்களின் ஆன்மாக்கள் உள்ளன\" என்று பதிலளித்தார்கள்.\n\r\n\n\r\nஅது ஏழாவது வானம் என்ற இந்தக் கூற்றை மற்றவர்களும் கூறியுள்ளனர். ﴾كَلَّا إِنَّ كِتَابَ الْأَبْرَارِ لَفِي عِلِّيِّينَ﴿ (அப்படியல்ல! நிச்சயமாக நல்லோர்களின் பதிவுப் புத்தகம் `இல்லிய்யீனில் இருக்கிறது.) என்ற அல்லாஹ்வின் வசனம் குறித்து அலி பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிப்பதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் சுவனமாகும்\" என்று கூறினார்கள். இது 'ஸித்ரத்துல் முன்தஹா'வில் அமைந்துள்ளது என்று இவர்களைத் தவிர பிற அறிஞர்களும் கூறியுள்ளனர்.\n\r\n\n\r\n`இல்லிய்யீன்' என்ற சொல் 'உலுவ்' (உயர்வு) என்ற சொல்லிலிருந்து பெறப்பட்டது என்பது வெளிப்படையான பொருளாகும். ஒரு விஷயம் எந்தளவுக்கு உயர்ந்து மேலோங்குகிறதோ, அந்தளவுக்கு அது மகத்தானதாகவும் மேன்மையானதாகவும் மாறுகிறது. எனவேதான், அல்லாஹ் ﴾وَمَا أَدْرَاكَ مَا عِلِّيُّونَ﴿ (`இல்லிய்யீன்' என்றால் என்னவென்று உமக்கு எது அறிவிக்கும்?) என்று கூறி அதன் மகத்துவத்தை உயர்த்திக் காட்டுகிறான்.\n\r\n\n\r\nபின்னர், அவர்களுக்கு எழுதப்படுவதை உறுதிப்படுத்தும் விதமாக அல்லாஹ் கூறுகிறான்: ﴾كِتَابٌ مَّرْقُومٌ * يَشْهَدُهُ الْمُقَرَّبُونَ﴿ ((அது) எழுதப்பட்ட ஒரு பதிவாகும். (அல்லாஹ்விடம்) நெருக்கமானவர்கள் அதற்குச் சாட்சியாக இருப்பார்கள்.) அவர்கள் வானவர்கள் என்று கத்தாதா (ரழி) அவர்கள் கூறியுள்ளார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள், \"ஒவ்வொரு வானத்திலும் அல்லாஹ்வுக்கு மிக நெருக்கமானவர்கள் அதனை நேரில் காண்பார்கள்\" என்று கூறியதாக அல்-அவ்ஃபீ (ரழி) அறிவிக்கிறார்கள்.\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்: ﴾إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ﴿ (நிச்சயமாக நல்லோர்கள் பேரின்பத்தில் இருப்பார்கள்.) அதாவது, மறுமை நாளில் அவர்கள் நிலையான இன்பத்திலும், அனைத்து விதமான அருட்கொடைகளையும் கொண்ட சொர்க்கச் சோலைகளிலும் இருப்பார்கள்.\n\r\n\n\r\n﴾عَلَى الْأَرَائِكِ﴿ (உயர்ந்த ஆசனங்களின் மீது,) இவை விதானங்களுக்குக் கீழே அமைக்கப்பட்டிருக்கும் ஆசனங்களாகும், அவற்றின் மீது அமர்ந்து கொண்டு அவர்கள் பார்த்துக் கொண்டிருப்பார்கள். \"இதன் பொருள், அவர்கள் தங்களது ஆட்சிப் பரப்பையும், அல்லாஹ் தங்களுக்கு வழங்கியுள்ள முடிவில்லாத, அழியாத அருட்கொடைகளையும் பார்த்துக் கொண்டிருப்பார்கள்\" என்று கூறப்படுகிறது. மேலும், ﴾عَلَى الْأَرَائِكِ يَنظُرُونَ﴿ (ஆசனங்களின் மீது அமர்ந்து பார்த்துக் கொண்டிருப்பார்கள்) என்பதற்கு \"அவர்கள் கண்ணியமும் வல்லமையும் மிக்க அல்லாஹ்வைப் பார்த்துக் கொண்டிருப்பார்கள்\" என்றும் விளக்கம் அளிக்கப்பட்டுள்ளது.\n\r\n\n\r\nஇது தீயவர்களைப் பற்றிக் கூறப்பட்டதற்கு நேர்மாறானதாகும்: ﴾كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ﴿ (அப்படியல்ல! நிச்சயமாக அவர்கள் அந்நாளில் தங்கள் இறைவனைப் பார்க்க முடியாமல் திரையிடப்படுவார்கள். -83:15). எனவே, இந்த நல்லோர்கள் தங்களது உயர்ந்த ஆசனங்களிலும் மஞ்சங்களிலும் அமர்ந்திருக்கும் நிலையில், அல்லாஹ்வைத் தரிசிக்க அனுமதிக்கப்படுவார்கள் என்று குறிப்பிடப்பட்டுள்ளது.\n\r\n\n\r\nஅல்லாஹ்வின் வசனமான ﴾تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ﴿ (அவர்களுடைய முகங்களில் இன்பத்தின் பொலிவை நீர் அறிவீர்) என்பதன் பொருள்: 'நீர் அவர்களைப் பார்க்கும்போது, அவர்களது முகங்களில் இன்பத்தின் பிரகாசத்தைக் காண்பீர்'. அந்தப் பேரின்பத்தின் காரணமாக அவர்கள் அனுபவிக்கும் செழிப்பு, கண்ணியம், மகிழ்ச்சி, மனநிறைவு மற்றும் அதிகாரம் ஆகியவற்றையே இது வர்ணிக்கிறது.\n\r\n\n\r\nஅல்லாஹ்வின் வசனமான ﴾يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ﴿ (முத்திரையிடப்பட்ட தூய்மையான பானத்திலிருந்து அவர்கள் புகட்டப்படுவார்கள்) என்பது, அவர்கள் சொர்க்கத்தின் மதுவை அருந்துவார்கள் என்பதைக் குறிக்கிறது. 'அர்-ரஹீக்' என்பது சொர்க்கத்து மதுவின் பெயர்களில் ஒன்றாகும் என்று இப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரழி), அல்-ஹஸன் (ரழி), கத்தாதா (ரழி) மற்றும் இப்னு ஸைத் (ரழி) ஆகியோர் கூறியுள்ளனர்.\n\r\n\n\r\n﴾خِتَامُهُ مِسْكٌ﴿ (அதன் முத்திரை கஸ்தூரியாகும்) என்ற வசனத்தைப் பற்றி இப்னு மஸ்ஊத் (ரழி) அவர்கள், \"இதன் பொருள், அது கஸ்தூரியுடன் கலக்கப்பட்டிருக்கும்\" என்று கூறினார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அல்-அவ்ஃபீ (ரழி) அறிவிக்கிறார்கள்: \"அல்லாஹ் அந்த மதுவை நறுமணம் மிக்கதாக ஆக்குவான்; அவன் அதில் இறுதியாகச் சேர்க்கும் பொருள் கஸ்தூரியாக இருக்கும். எனவேதான் அது கஸ்தூரியால் முத்திரையிடப்படும்.\" கத்தாதா (ரழி) அவர்களும் அத்-தஹ்ஹாக் (ரழி) அவர்களும் இதையே கூறியுள்ளனர்.\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்: ﴾وَفِي ذَلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ﴿ (மேலும் இதற்காகவே போட்டியிடுபவர்கள் போட்டியிடட்டும்.) அதாவது, இத்தகைய நிலையை அடைவதற்காக, போட்டியிடுபவர்கள் போட்டியிடட்டும், மேலும் அதிகமாகப் பெறுவதற்கு முயற்சி செய்யட்டும். இத்தகைய பாக்கியங்களை நோக்கியே போட்டியாளர்கள் ஒருவருக்கொருவர் முந்திச் செல்ல வேண்டும். இது அல்லாஹ்வின் மற்றொரு வசனத்தைப் போன்றதாகும்: ﴾لِمِثْلِ هَذَا فَلْيَعْمَلِ الْعَامِلُونَ﴿ (செயல்படுபவர்கள் இத்தகையவற்றிற்காகவே செயல்படட்டும் - 37:61).\n\r\n\n\r\nஅல்லாஹ் மேலும் கூறுகிறான்: ﴾وَمِزَاجُهُ مِن تَسْنِيمٍ﴿ (அதன் கலவை 'தஸ்னீம்' என்பதாகும்.) அதாவது, இங்கு விவரிக்கப்படும் மது தஸ்னீமுடன் கலக்கப்பட்டுள்ளது. 'தஸ்னீம்' என்பது சொர்க்கவாசிகளின் பானங்களிலேயே மிகச் சிறந்ததும் உயர்ந்ததுமான ஒரு பானமாகும். இதனை அபூ ஸாலிஹ் (ரழி) அவர்களும் அத்-தஹ்ஹாக் (ரழி) அவர்களும் கூறியுள்ளனர்.\n\r\n\n\r\nஎனவேதான் அல்லாஹ் கூறுகிறான்: ﴾عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ﴿ ((அது) ஒரு நீரூற்றாகும்; அதிலிருந்து அல்லாஹ்வுக்கு நெருக்கமானவர்கள் அருந்துவார்கள் - 83:28). அதாவது, அல்லாஹ்வுக்கு நெருக்கமானவர்கள் அதிலிருந்து கலப்படமின்றி அருந்துவார்கள்; மேலும் வலப்பக்கத் தோழர்களுக்கு (அஸ்ஹாபுல் யமீன்) அத்துடன் கலக்கப்பட்ட பானம் வழங்கப்படும். இதனை இப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), மஸ்ரூக் (ரழி), கத்தாதா (ரழி) மற்றும் பலர் கூறியுள்ளனர்."},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=36\" class=\"link\">83:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:36 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=36\" class=\"link\">83:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:36 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=36\" class=\"link\">83:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:36 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=36\" class=\"link\">83:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:36 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=36\" class=\"link\">83:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:36 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=36\" class=\"link\">83:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:36 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=83&ayah=36\" class=\"link\">83:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 83:36 ஐ பார்க்கவும்"},"36":{"html":"<strong>குற்றவாளிகளின் தீய நடத்தையும், அவர்கள் நம்பிக்கையாளர்களைக் கேலி செய்ததும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَجْرَمُواْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">يَضْحَكُونَ</span> - <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَرُّواْ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَتَغَامَزُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nகுற்றவாளிகள் இவ்வுலக வாழ்க்கையில் நம்பிக்கையாளர்களைப் பார்த்துச் சிரித்துக் கொண்டிருந்தார்கள் என்று அல்லாஹ் கூறுகிறான். அதாவது, அவர்கள் நம்பிக்கையாளர்களைக் கேலி செய்ததோடு, அவர்களை இழிவாகவும் கருதினார்கள். அவர்கள் நம்பிக்கையாளர்களைக் கடந்து செல்லும் போதெல்லாம், அவர்களை ஏளனம் செய்யும் விதமாகத் தங்களுக்குள் கண்ணால் ஜாடை காட்டிக்கொள்வார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">انقَلَبُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَهْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">انقَلَبُواْ</span> <span class=\"quran-arabic-font text-success\">فَكِهِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் தங்கள் குடும்பத்தாரிடம் திரும்பும்போது, மகிழ்ச்சியோடு திரும்புவார்கள்.) அதாவது, இந்தக் குற்றவாளிகள் தங்கள் வீடுகளுக்குத் திரும்பும்போது மிகவும் திருப்தியுடன் திரும்புவார்கள். இதன் பொருள், அவர்கள் எதை விரும்புகிறார்களோ அதை அங்கே கண்டுகொள்கிறார்கள். இவ்வளவு இருந்தும், அல்லாஹ் தங்களுக்கு வழங்கிய அருட்கொடைகளுக்காக அவர்கள் அவனுக்கு நன்றி செலுத்துவதில்லை; மாறாக, நம்பிக்கையாளர்களை இழிவுபடுத்துவதிலும் அவர்கள் மீது பொறாமை கொள்வதிலுமே தங்களை ஈடுபடுத்திக் கொள்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">رَأَوْهُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاَءِ</span> <span class=\"quran-arabic-font text-success\">لَضَآلُّونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் நம்பிக்கையாளர்களைக் காணும்போது, \"நிச்சயமாக இவர்கள் வழிதவறியவர்கள்\" என்று கூறுவார்கள்.) அதாவது, நம்பிக்கையாளர்கள் தங்களது (நிராகரிப்பாளர்களின்) மார்க்கத்தைத் தவிர்த்து வேறு மார்க்கத்தைப் பின்பற்றுவதால் அவர்கள் இவ்வாறு கூறுகிறார்கள். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">حَافِظِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆனால், அவர்கள் மீது கண்காணிப்பாளர்களாக இவர்கள் அனுப்பப்படவில்லை.) அதாவது, இந்த நம்பிக்கையாளர்களின் செயல்களையும் பேச்சுகளையும் கண்காணிக்கும் பாதுகாவலர்களாக இந்தக் குற்றவாளிகள் அனுப்பப்படவில்லை. இந்த அநியாயக்காரர்கள் அவர்களுக்குப் பொறுப்பாளிகளாக ஆக்கப்படவில்லை. அப்படியிருக்க, அவர்கள் ஏன் நம்பிக்கையாளர்களைப் பற்றி இவ்வளவு கவலைப்படுகிறார்கள், ஏன் அவர்களைத் தங்கள் கவனத்தின் மையமாக ஆக்கிக் கொண்டிருக்கிறார்கள்? இது குறித்து அல்லாஹ் மற்றோர் இடத்தில் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">اخْسَئُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكَلِّمُونِ</span> <span class=\"quran-arabic-font text-success\">﴿﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فَرِيقٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِى</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">فَاغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">وَارْحَمْنَا</span> <span class=\"quran-arabic-font text-success\">وَأَنتَ</span> <span class=\"quran-arabic-font text-success\">خَيْرُ</span> <span class=\"quran-arabic-font text-success\">الرَّاحِمِينَ</span> - <span class=\"quran-arabic-font text-success\">فَاتَّخَذْتُمُوهُمْ</span> <span class=\"quran-arabic-font text-success\">سِخْرِيّاً</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">أَنسَوْكُمْ</span> <span class=\"quran-arabic-font text-success\">ذِكْرِى</span> <span class=\"quran-arabic-font text-success\">وَكُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">تَضْحَكُونَ</span> - <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">جَزَيْتُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">صَبَرُواْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَآئِزُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவன் (அல்லாஹ்) கூறுவான்: \"இழிவடைந்தவர்களாக இதிலேயே கிடருங்கள்! என்னிடம் பேசாதீர்கள்!\" நிச்சயமாக எனது அடியார்களில் ஒரு பிரிவினர், \"எங்கள் இறைவனே! நாங்கள் நம்பிக்கை கொண்டோம், எனவே எங்களுக்கு மன்னிப்பு வழங்குவாயாக! எங்கள் மீது கருணை காட்டுவாயாக! கருணையாளர்களிலெல்லாம் நீயே மிகச் சிறந்தவன்\" என்று வேண்டிக் கொண்டிருந்தார்கள். ஆனால் நீங்களோ அவர்களைப் பரிகாசப் பொருளாக ஆக்கிக் கொண்டீர்கள். எந்தளவுக்கென்றால், அவர்களைப் பரிகாசம் செய்வதில் நீங்கள் மூழ்கிப்போய் எனது நினைவையே மறந்துவிட்டீர்கள்; நீங்கள் அவர்களைப் பார்த்துச் சிரித்துக் கொண்டும் இருந்தீர்கள். அவர்கள் பொறுமையாக இருந்ததற்காக இன்றைய தினம் நான் அவர்களுக்கு நற்கூலி வழங்கியுள்ளேன்; நிச்சயமாக அவர்களே வெற்றியாளர்கள்.) (<a href=\"qurandisp.php?sura=23&ayah=108\" class=\"link\">23:108</a>-111) எனவே, அல்லாஹ் இங்கு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَالْيَوْمَ﴿</span><br />\r\n<br />\r\n(ஆனால் இந்நாளில்) அதாவது, மறுமை நாளில்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْكُفَّارِ</span> <span class=\"quran-arabic-font text-success\">يَضْحَكُونَ﴿</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டவர்கள், நிராகரிப்பாளர்களைப் பார்த்துச் சிரிப்பார்கள்.) அதாவது, அன்று அவர்கள் தங்களைப் பார்த்துச் சிரித்ததற்கான கைமாறாக (பிரதிபலனாக) இவர்கள் அவர்களைப் பார்த்துச் சிரிப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾عَلَى</span> <span class=\"quran-arabic-font text-success\">الاٌّرَآئِكِ</span> <span class=\"quran-arabic-font text-success\">يَنظُرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அலங்கரிக்கப்பட்ட ஆசனங்களில் அமர்ந்து பார்த்துக் கொண்டிருப்பார்கள்.) அதாவது, 'தாங்கள் வழிதவறியவர்கள்' என்று சுமத்தப்பட்ட பொய்க் குற்றச்சாட்டுகளைப் பொறுமையுடன் சகித்துக் கொண்டதற்கான கூலியாக அவர்கள் அல்லாஹ்வைப் பார்த்துக் கொண்டிருப்பார்கள். அவர்கள் ஒருபோதும் வழிதவறியவர்கள் அல்ல; மாறாக அவர்கள் அல்லாஹ்வின் நெருக்கமான அவ்லியாக்கள் (நேசர்கள்) ஆவார்கள். அவர்கள் கண்ணியம் நிறைந்த அந்த இடத்தில் தங்கள் இறைவனைத் தரிசிப்பார்கள். அல்லாஹ்வின் இந்தக் கூற்றைப் பற்றி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾هَلْ</span> <span class=\"quran-arabic-font text-success\">ثُوِّبَ</span> <span class=\"quran-arabic-font text-success\">الْكُفَّارُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَفْعَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் தாங்கள் செய்து கொண்டிருந்தவற்றுக்காகக் கூலி கொடுக்கப்பட்டு விட்டார்களா?) அதாவது, 'நிராகரிப்பாளர்கள் நம்பிக்கையாளர்களைக் கேலி செய்ததற்கும் இழிவுபடுத்தியதற்கும் அவர்களுக்குரிய தண்டனை வழங்கப்பட்டுவிட்டதா இல்லையா?' நிச்சயமாக அவர்கள் செய்த செயல்களுக்காக முழுமையாகவும் பூரணமாகவும் கூலி (தண்டனை) வழங்கப்படுவார்கள் என்பதே இதன் பொருளாகும். இத்துடன் ஸூரத்துல் முதஃப்ஃபிஃபீனின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"குற்றவாளிகளின் தீய நடத்தையும், அவர்கள் நம்பிக்கையாளர்களைக் கேலி செய்ததும்\n\r\n\n\r\n﴾إِنَّ الَّذِينَ أَجْرَمُواْ كَانُواْ مِنَ الَّذِينَ ءَامَنُواْ يَضْحَكُونَ - وَإِذَا مَرُّواْ بِهِمْ يَتَغَامَزُونَ ﴿\n\r\n\n\r\nகுற்றவாளிகள் இவ்வுலக வாழ்க்கையில் நம்பிக்கையாளர்களைப் பார்த்துச் சிரித்துக் கொண்டிருந்தார்கள் என்று அல்லாஹ் கூறுகிறான். அதாவது, அவர்கள் நம்பிக்கையாளர்களைக் கேலி செய்ததோடு, அவர்களை இழிவாகவும் கருதினார்கள். அவர்கள் நம்பிக்கையாளர்களைக் கடந்து செல்லும் போதெல்லாம், அவர்களை ஏளனம் செய்யும் விதமாகத் தங்களுக்குள் கண்ணால் ஜாடை காட்டிக்கொள்வார்கள்.\n\r\n\n\r\n﴾وَإِذَا انقَلَبُواْ إِلَى أَهْلِهِمْ انقَلَبُواْ فَكِهِينَ ﴿\n\r\n\n\r\n(மேலும் அவர்கள் தங்கள் குடும்பத்தாரிடம் திரும்பும்போது, மகிழ்ச்சியோடு திரும்புவார்கள்.) அதாவது, இந்தக் குற்றவாளிகள் தங்கள் வீடுகளுக்குத் திரும்பும்போது மிகவும் திருப்தியுடன் திரும்புவார்கள். இதன் பொருள், அவர்கள் எதை விரும்புகிறார்களோ அதை அங்கே கண்டுகொள்கிறார்கள். இவ்வளவு இருந்தும், அல்லாஹ் தங்களுக்கு வழங்கிய அருட்கொடைகளுக்காக அவர்கள் அவனுக்கு நன்றி செலுத்துவதில்லை; மாறாக, நம்பிக்கையாளர்களை இழிவுபடுத்துவதிலும் அவர்கள் மீது பொறாமை கொள்வதிலுமே தங்களை ஈடுபடுத்திக் கொள்கிறார்கள்.\n\r\n\n\r\n﴾وَإِذَا رَأَوْهُمْ قَالُواْ إِنَّ هَـؤُلاَءِ لَضَآلُّونَ ﴿\n\r\n\n\r\n(மேலும் அவர்கள் நம்பிக்கையாளர்களைக் காணும்போது, \"நிச்சயமாக இவர்கள் வழிதவறியவர்கள்\" என்று கூறுவார்கள்.) அதாவது, நம்பிக்கையாளர்கள் தங்களது (நிராகரிப்பாளர்களின்) மார்க்கத்தைத் தவிர்த்து வேறு மார்க்கத்தைப் பின்பற்றுவதால் அவர்கள் இவ்வாறு கூறுகிறார்கள். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾وَمَآ أُرْسِلُواْ عَلَيْهِمْ حَافِظِينَ ﴿\n\r\n\n\r\n(ஆனால், அவர்கள் மீது கண்காணிப்பாளர்களாக இவர்கள் அனுப்பப்படவில்லை.) அதாவது, இந்த நம்பிக்கையாளர்களின் செயல்களையும் பேச்சுகளையும் கண்காணிக்கும் பாதுகாவலர்களாக இந்தக் குற்றவாளிகள் அனுப்பப்படவில்லை. இந்த அநியாயக்காரர்கள் அவர்களுக்குப் பொறுப்பாளிகளாக ஆக்கப்படவில்லை. அப்படியிருக்க, அவர்கள் ஏன் நம்பிக்கையாளர்களைப் பற்றி இவ்வளவு கவலைப்படுகிறார்கள், ஏன் அவர்களைத் தங்கள் கவனத்தின் மையமாக ஆக்கிக் கொண்டிருக்கிறார்கள்? இது குறித்து அல்லாஹ் மற்றோர் இடத்தில் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\n﴾قَالَ اخْسَئُواْ فِيهَا وَلاَ تُكَلِّمُونِ ﴿﴾إِنَّهُ كَانَ فَرِيقٌ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّاحِمِينَ - فَاتَّخَذْتُمُوهُمْ سِخْرِيّاً حَتَّى أَنسَوْكُمْ ذِكْرِى وَكُنْتُمْ مِّنْهُمْ تَضْحَكُونَ - إِنِّى جَزَيْتُهُمُ الْيَوْمَ بِمَا صَبَرُواْ أَنَّهُمْ هُمُ الْفَآئِزُونَ ﴿\n\r\n\n\r\n(அவன் (அல்லாஹ்) கூறுவான்: \"இழிவடைந்தவர்களாக இதிலேயே கிடருங்கள்! என்னிடம் பேசாதீர்கள்!\" நிச்சயமாக எனது அடியார்களில் ஒரு பிரிவினர், \"எங்கள் இறைவனே! நாங்கள் நம்பிக்கை கொண்டோம், எனவே எங்களுக்கு மன்னிப்பு வழங்குவாயாக! எங்கள் மீது கருணை காட்டுவாயாக! கருணையாளர்களிலெல்லாம் நீயே மிகச் சிறந்தவன்\" என்று வேண்டிக் கொண்டிருந்தார்கள். ஆனால் நீங்களோ அவர்களைப் பரிகாசப் பொருளாக ஆக்கிக் கொண்டீர்கள். எந்தளவுக்கென்றால், அவர்களைப் பரிகாசம் செய்வதில் நீங்கள் மூழ்கிப்போய் எனது நினைவையே மறந்துவிட்டீர்கள்; நீங்கள் அவர்களைப் பார்த்துச் சிரித்துக் கொண்டும் இருந்தீர்கள். அவர்கள் பொறுமையாக இருந்ததற்காக இன்றைய தினம் நான் அவர்களுக்கு நற்கூலி வழங்கியுள்ளேன்; நிச்சயமாக அவர்களே வெற்றியாளர்கள்.) (23:108-111) எனவே, அல்லாஹ் இங்கு கூறுகிறான்:\n\r\n\n\r\n﴾فَالْيَوْمَ﴿\n\r\n\n\r\n(ஆனால் இந்நாளில்) அதாவது, மறுமை நாளில்.\n\r\n\n\r\n﴾الَّذِينَ ءَامَنُواْ مِنَ الْكُفَّارِ يَضْحَكُونَ﴿\n\r\n\n\r\n(நம்பிக்கை கொண்டவர்கள், நிராகரிப்பாளர்களைப் பார்த்துச் சிரிப்பார்கள்.) அதாவது, அன்று அவர்கள் தங்களைப் பார்த்துச் சிரித்ததற்கான கைமாறாக (பிரதிபலனாக) இவர்கள் அவர்களைப் பார்த்துச் சிரிப்பார்கள்.\n\r\n\n\r\n﴾عَلَى الاٌّرَآئِكِ يَنظُرُونَ ﴿\n\r\n\n\r\n(அலங்கரிக்கப்பட்ட ஆசனங்களில் அமர்ந்து பார்த்துக் கொண்டிருப்பார்கள்.) அதாவது, 'தாங்கள் வழிதவறியவர்கள்' என்று சுமத்தப்பட்ட பொய்க் குற்றச்சாட்டுகளைப் பொறுமையுடன் சகித்துக் கொண்டதற்கான கூலியாக அவர்கள் அல்லாஹ்வைப் பார்த்துக் கொண்டிருப்பார்கள். அவர்கள் ஒருபோதும் வழிதவறியவர்கள் அல்ல; மாறாக அவர்கள் அல்லாஹ்வின் நெருக்கமான அவ்லியாக்கள் (நேசர்கள்) ஆவார்கள். அவர்கள் கண்ணியம் நிறைந்த அந்த இடத்தில் தங்கள் இறைவனைத் தரிசிப்பார்கள். அல்லாஹ்வின் இந்தக் கூற்றைப் பற்றி:\n\r\n\n\r\n﴾هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُواْ يَفْعَلُونَ ﴿\n\r\n\n\r\n(நிராகரிப்பாளர்கள் தாங்கள் செய்து கொண்டிருந்தவற்றுக்காகக் கூலி கொடுக்கப்பட்டு விட்டார்களா?) அதாவது, 'நிராகரிப்பாளர்கள் நம்பிக்கையாளர்களைக் கேலி செய்ததற்கும் இழிவுபடுத்தியதற்கும் அவர்களுக்குரிய தண்டனை வழங்கப்பட்டுவிட்டதா இல்லையா?' நிச்சயமாக அவர்கள் செய்த செயல்களுக்காக முழுமையாகவும் பூரணமாகவும் கூலி (தண்டனை) வழங்கப்படுவார்கள் என்பதே இதன் பொருளாகும். இத்துடன் ஸூரத்துல் முதஃப்ஃபிஃபீனின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
